function setQualityGroup(group) {
  const allowed = new Set(["persona", "governance", "production"]);
  const active = allowed.has(group) ? group : "persona";
  $$(".quality-tab").forEach((button) => {
    const selected = button.dataset.qualityTab === active;
    button.classList.toggle("active", selected);
    button.setAttribute("aria-selected", selected ? "true" : "false");
  });
  const grid = $("#qualityPanelGrid");
  if (grid) grid.dataset.activeQualityGroup = active;
  $$("[data-quality-group]").forEach((panel) => {
    panel.hidden = panel.dataset.qualityGroup !== active;
  });
  if (active === "production") {
    renderAgentTraceHistoryPanel();
    renderOkfValidationStatusPanel();
  }
}

