async function safeRefreshStaticN8nReplayStatus() {
  if (!staticPagesMode) return;
  try {
    const response = await fetch(frontendAssetUrl(N8N_CONTRACT_REPLAY_STATUS_PATH), { cache: "no-store" });
    if (!response.ok) throw new Error(`Replay status unavailable: ${response.status}`);
    const replayStatus = await response.json();
    mergeStaticN8nReplayStatus(replayStatus);
    renderAgentOperatingModelPanel();
    renderChatContractBadges();
  } catch (error) {
    console.warn("Static n8n fixture replay status refresh failed", error);
  }
}

async function safeRefreshStaticOkfValidationStatus() {
  if (!staticPagesMode) {
    renderOkfValidationStatusPanel();
    return;
  }
  try {
    const response = await fetch(frontendAssetUrl(OKF_VALIDATION_STATUS_PATH), { cache: "no-store" });
    if (!response.ok) throw new Error(`OKF status unavailable: ${response.status}`);
    state.okfValidationStatus = await response.json();
    renderOkfValidationStatusPanel();
  } catch (error) {
    state.okfValidationStatus = {
      status: "blocked",
      generated_at: "",
      statuses: ["documented", "blocked"],
      summary: {},
      checks: [],
      paths: {},
      error: compactError(error.message),
    };
    renderOkfValidationStatusPanel();
    console.warn("Static OKF validation status refresh failed", error);
  }
}

function mergeStaticN8nReplayStatus(replayStatus = {}) {
  if (!state.n8nAgentContracts || !Array.isArray(state.n8nAgentContracts.contracts)) return;
  const replayByAgent = new Map((replayStatus.agents || []).map((agent) => [agent.agent_id, agent]));
  state.n8nAgentContracts = {
    ...state.n8nAgentContracts,
    replay_status: replayStatus.status || "unknown",
    replay_case_count: Number(replayStatus.case_count || 0),
    replay_fixture_count: Number(replayStatus.fixture_count || 0),
    replay_generated_at: replayStatus.generated_at || "",
    contracts: state.n8nAgentContracts.contracts.map((contract) => {
      const replay = replayByAgent.get(contract.agent_id);
      if (!replay) return contract;
      const configured = Boolean(contract.webhook_configured);
      return {
        ...contract,
        contract_version: replay.contract_version || contract.contract_version,
        replay_status: replay.status || "unknown",
        replay_case_count: Number(replay.case_count || 0),
        tested_cases: replay.tested_cases || [],
        live_status: configured ? "configured" : (replay.live_status || "not_configured"),
        statuses: [
          "documented",
          replay.status === "passed" ? "fixture ready" : "blocked",
          replay.status === "passed" ? "contract tested" : "blocked",
          configured ? "n8n connected" : "blocked",
        ],
        blocker: configured ? "" : replay.blocker || contract.blocker,
      };
    }),
  };
}

function renderAgentOperatingModelPanel() {
  const target = $("#agentOperatingModelPanel");
  if (!target) return;
  const model = state.agentOperatingModel || {};
  const agents = Array.isArray(model.top_level_agents) ? model.top_level_agents : [];
  if (!agents.length) {
    target.innerHTML = renderEmptyState("No top-level agent model loaded.");
    return;
  }
  target.innerHTML = `
    <div class="agent-model-grid top-level-agent-grid">
      ${agents.map((agent) => `
        <article class="top-level-agent-card ${safeGraphClass(agent.id || "agent")}">
          <div class="activity-meta">
            <span class="badge">${escapeHtml(agent.group || "agent")}</span>
            <small>${escapeHtml(agent.n8n_contract || "no contract")}</small>
          </div>
          <h3>${escapeHtml(agent.name || agent.id || "Agent")}</h3>
          <p>${escapeHtml(agent.purpose || "")}</p>
          <div class="agent-consumer-list">
            ${(agent.owns || []).slice(0, 5).map((item) => `<span>${escapeHtml(item)}</span>`).join("")}
          </div>
          ${renderInternalAgentComponents(agent)}
          <small>${escapeHtml((agent.subagents || []).length)} subagents · approval remains human-gated</small>
        </article>
      `).join("")}
    </div>
    ${renderN8nContractReadinessPanel(agents)}
  `;
}

function renderInternalAgentComponents(agent = {}) {
  const components = Array.isArray(agent.internal_components) ? agent.internal_components : [];
  if (!components.length) return "";
  return `
    <div class="internal-component-list">
      ${components.map((component) => `
        <span>
          <strong>${escapeHtml(component.name || component.id || "Internal component")}</strong>
          <small>${escapeHtml(component.purpose || "Internal runtime component")}</small>
        </span>
      `).join("")}
    </div>
  `;
}

function renderN8nContractReadinessPanel(agents = []) {
  const contracts = state.n8nAgentContracts?.contracts || [];
  const contractByAgent = new Map(contracts.map((contract) => [contract.agent_id, contract]));
  const replaySummary = state.n8nAgentContracts?.replay_status
    ? ` · replay ${state.n8nAgentContracts.replay_status}: ${state.n8nAgentContracts.replay_case_count || 0} cases`
    : "";
  return `
    <div class="agent-contract-readiness-head">
      <span class="badge">n8n runtime boundary</span>
      <small>${escapeHtml(`${state.n8nAgentContracts?.configured_count ?? 0}/${state.n8nAgentContracts?.contract_count ?? agents.length} webhooks configured${replaySummary}`)}</small>
    </div>
    <div class="agent-contract-readiness">
      ${agents.map((agent) => renderN8nContractReadiness(agent, contractByAgent.get(agent.id))).join("")}
    </div>
    ${renderAgentContractActionResult()}
  `;
}

function renderN8nContractReadiness(agent = {}, readiness = null) {
  const contractSource = readiness?.source || agent.n8n_contract || "";
  const configured = Boolean(readiness?.webhook_configured);
  const probe = state.n8nLiveProbeResults?.[agent.id || readiness?.agent_id || ""];
  const replayPassed = readiness?.replay_status === "passed";
  const status = readiness ? (configured ? "configured" : (replayPassed ? "fixture replay passed" : "contract ready")) : "missing contract";
  const statusItems = Array.isArray(readiness?.statuses)
    ? readiness.statuses
    : ["documented", contractSource ? "fixture ready" : "blocked", configured ? "n8n connected" : "blocked"];
  const envVar = {
    actor_twin: "N8N_ACTOR_TWIN_WEBHOOK_URL",
    knowledge_fabric_agent: "N8N_KNOWLEDGE_FABRIC_WEBHOOK_URL",
    agentic_butler: "N8N_AGENTIC_BUTLER_WEBHOOK_URL",
  }[agent.id] || readiness?.webhook_env_var || "N8N_WEBHOOK_URL";
  return `
    <article class="agent-contract-card ${configured ? "ready" : "pending"}">
      <span class="queue-kind">${escapeHtml(status)}</span>
      <strong>${escapeHtml(readiness?.webhook_env_var || envVar)}</strong>
      <p>${escapeHtml(contractSource)}</p>
      <div class="agent-contract-status-strip" aria-label="Contract statuses">
        ${statusItems.map((item) => `<span class="${safeGraphClass(item)}">${escapeHtml(item)}</span>`).join("")}
      </div>
      ${readiness?.source_url || readiness?.backlog_url ? `
        <div class="agent-contract-links">
          ${readiness?.source_url ? `<a href="${escapeHtml(readiness.source_url)}" target="_blank" rel="noreferrer">Fixture</a>` : ""}
          ${readiness?.backlog_url ? `<a href="${escapeHtml(readiness.backlog_url)}" target="_blank" rel="noreferrer">Backlog</a>` : ""}
          ${state.n8nAgentContracts?.replay_status_url ? `<a href="${escapeHtml(state.n8nAgentContracts.replay_status_url)}" target="_blank" rel="noreferrer">Replay</a>` : ""}
        </div>
      ` : ""}
      <small>${escapeHtml(configured ? "Webhook env var is configured. Run UAT before production use." : "Fixture replay is local/static. Add webhook env var to activate runtime forwarding.")}</small>
      ${readiness?.replay_case_count ? `<small>${escapeHtml(`${readiness.replay_case_count} contract cases replayed locally`)}</small>` : ""}
      ${probe ? `<small class="${escapeHtml(probe.status === "connected" ? "ready" : probe.status === "blocked" ? "warning-copy" : "muted-inline")}">${escapeHtml(`Live probe: ${probe.status} · ${probe.detail || ""}`)}</small>` : ""}
      ${readiness?.blocker ? `<small>${escapeHtml(readiness.blocker)}</small>` : ""}
      <div class="button-row tight">
        <button class="secondary small" type="button" data-agent-contract-test="${escapeHtml(agent.id || "")}">Test contract</button>
        <button class="secondary small" type="button" data-agent-live-probe="${escapeHtml(agent.id || "")}">Probe live</button>
        <button class="secondary small" type="button" data-agent-uat-payload="${escapeHtml(agent.id || "")}">Show UAT payload</button>
        ${agent.id === "knowledge_fabric_agent" ? `
          <button class="secondary small" type="button" data-knowledge-fabric-dry-run="ingest">Ingest payload</button>
          <button class="secondary small" type="button" data-knowledge-fabric-dry-run="graph">Graph payload</button>
          <button class="secondary small" type="button" data-knowledge-fabric-dry-run="vector">Vector payload</button>
        ` : ""}
      </div>
    </article>
  `;
}

function renderAgentContractActionResult() {
  const contractResult = state.n8nContractTestResult;
  const dryRun = state.knowledgeFabricDryRunResult;
  if (!contractResult && !dryRun) return "";
  return `
    <div class="agent-contract-result">
      ${contractResult ? `
        <article class="output-card">
          <span class="badge">Contract test</span>
          <strong>${escapeHtml(contractResult.agent_name || contractResult.agent_id || "n8n contract")}</strong>
          <p>${escapeHtml(`${contractResult.status || "checked"} · ${contractResult.webhook_env_var || ""}`)}</p>
          <pre class="output compact-output">${escapeHtml(JSON.stringify(contractResult.payload || contractResult, null, 2))}</pre>
        </article>
      ` : ""}
      ${dryRun ? `
        <article class="output-card">
          <span class="badge">Knowledge Fabric dry-run</span>
          <strong>${escapeHtml(dryRun.payload?.operation || "operation")}</strong>
          <p>${escapeHtml(`${dryRun.status || "prepared"} · ${dryRun.webhook_env_var || ""}`)}</p>
          <pre class="output compact-output">${escapeHtml(JSON.stringify(dryRun.payload || dryRun, null, 2))}</pre>
        </article>
      ` : ""}
    </div>
  `;
}

async function handleAgentOperatingModelClick(event) {
  const testButton = event.target.closest("[data-agent-contract-test]");
  if (testButton) {
    await testAgentContract(testButton.dataset.agentContractTest || "");
    return;
  }
  const probeButton = event.target.closest("[data-agent-live-probe]");
  if (probeButton) {
    await probeAgentContract(probeButton.dataset.agentLiveProbe || "");
    return;
  }
  const uatButton = event.target.closest("[data-agent-uat-payload]");
  if (uatButton) {
    showAgentUatPayload(uatButton.dataset.agentUatPayload || "");
    return;
  }
  const dryRunButton = event.target.closest("[data-knowledge-fabric-dry-run]");
  if (dryRunButton) {
    await prepareKnowledgeFabricDryRun(dryRunButton.dataset.knowledgeFabricDryRun || "ingest");
  }
}

async function testAgentContract(agentId) {
  if (!agentId) return;
  state.n8nContractTestResult = null;
  renderAgentOperatingModelPanel();
  try {
    const result = await postJson("/api/agents/n8n-contracts/test", {
      agent_id: agentId,
      twin: state.activeTwin,
      execute: false,
    });
    state.n8nContractTestResult = result;
    renderAgentOperatingModelPanel();
    showToast("n8n contract tested", `${result.agent_name || agentId}: ${result.status}`, "success");
  } catch (error) {
    showToast("n8n contract test failed", compactError(error.message), "error");
  }
}

function renderOkfValidationStatusPanel() {
  const target = $("#okfValidationStatusPanel");
  if (!target) return;
  const status = state.okfValidationStatus;
  if (!status) {
    target.innerHTML = renderEmptyState("OKF validation status has not been loaded yet.");
    return;
  }
  const summary = status.summary || {};
  const paths = status.paths || {};
  const checks = Array.isArray(status.checks) ? status.checks : [];
  const statusClass = status.status === "passed" ? "ready" : status.status === "blocked" ? "pending" : "warning";
  target.innerHTML = `
    <div class="okf-validation-summary ${statusClass}">
      <div>
        <span class="queue-kind">${escapeHtml(status.status || "unknown")}</span>
        <strong>${escapeHtml(`${summary.passed_check_count ?? 0}/${summary.check_count ?? 0} checks passed`)}</strong>
        <p>${escapeHtml(`${summary.example_fixture_count ?? 0} examples · ${summary.generated_ingest_file_count ?? 0} generated ingest files · ${summary.promotion_fixture_count ?? 0} promotion decisions`)}</p>
        ${status.generated_at ? `<small>${escapeHtml(`Generated ${formatShortDate(status.generated_at)}`)}</small>` : ""}
        ${status.error ? `<small class="warning-copy">${escapeHtml(status.error)}</small>` : ""}
      </div>
      <div class="agent-contract-status-strip">
        ${(status.statuses || []).map((item) => `<span class="${safeGraphClass(item)}">${escapeHtml(item)}</span>`).join("")}
      </div>
    </div>
    <div class="okf-validation-checks">
      ${checks.map((check) => `
        <article class="${check.status === "passed" ? "ready" : "pending"}">
          <strong>${escapeHtml(check.command || "OKF check")}</strong>
          <span>${escapeHtml(check.status || "unknown")}</span>
          <small>${escapeHtml(check.stdout || check.stderr || "")}</small>
        </article>
      `).join("") || renderEmptyState("No OKF validation checks are available.")}
    </div>
    <div class="agent-contract-links">
      ${paths.schema_doc ? `<a href="${escapeHtml(githubBlobUrl(paths.schema_doc))}" target="_blank" rel="noreferrer">Schema</a>` : ""}
      ${paths.fixture_root ? `<a href="${escapeHtml(githubBlobUrl(paths.fixture_root))}" target="_blank" rel="noreferrer">Fixtures</a>` : ""}
      ${paths.generated_root ? `<a href="${escapeHtml(githubBlobUrl(paths.generated_root))}" target="_blank" rel="noreferrer">Generated ingest</a>` : ""}
      ${paths.promotion_root ? `<a href="${escapeHtml(githubBlobUrl(paths.promotion_root))}" target="_blank" rel="noreferrer">Promotions</a>` : ""}
      ${paths.vector_adapter_example ? `<a href="${escapeHtml(githubBlobUrl(paths.vector_adapter_example))}" target="_blank" rel="noreferrer">Vector adapter</a>` : ""}
    </div>
  `;
}

function githubBlobUrl(repoPath = "") {
  const clean = String(repoPath || "").replace(/^\/+/, "");
  return `https://github.com/florianliepe/meids-app/blob/main/${encodeURI(clean).replaceAll("%2F", "/")}`;
}

async function probeAgentContract(agentId) {
  if (!agentId) return;
  const webhookUrl = getAgentWebhook(agentId);
  if (!webhookUrl) {
    state.n8nLiveProbeResults = {
      ...state.n8nLiveProbeResults,
      [agentId]: { status: "blocked", detail: "No runtime webhook configured." },
    };
    renderAgentOperatingModelPanel();
    showToast("Live probe blocked", `${agentDisplayName(agentId)} webhook is not configured.`, "warning");
    return;
  }
  if (staticPagesMode && !isN8nChatWebhook(webhookUrl)) {
    state.n8nLiveProbeResults = {
      ...state.n8nLiveProbeResults,
      [agentId]: { status: "configured", detail: "Webhook URL exists; live POST is disabled in static probe mode." },
    };
    renderAgentOperatingModelPanel();
    showToast("Live probe configured", `${agentDisplayName(agentId)} has a webhook URL.`, "success");
    return;
  }
  const envelope = buildAgentContractEnvelope(
    agentId,
    "contract_probe",
    "Contract readiness probe from MeIDs cockpit.",
    { execute: false },
    { probe: true, source_context: {} },
    { required: false, reason: "Readiness probe only." },
  );
  try {
    const result = await postAgentContractEnvelope(agentId, envelope, (fallbackEnvelope) => normalizeAgentContractResponse(agentId, {
      status: "completed",
      output: { answer: "Fixture probe completed." },
      trace: { trace_id: `trace_${fallbackEnvelope.request_id}`, stored: false },
    }, fallbackEnvelope, "fixture fallback"));
    state.n8nLiveProbeResults = {
      ...state.n8nLiveProbeResults,
      [agentId]: { status: result.runtime === "n8n connected" ? "connected" : "fixture", detail: result.trace_id || result.response?.request_id || "" },
    };
    renderAgentOperatingModelPanel();
    renderChatContractBadges();
    showToast("Live probe completed", `${agentDisplayName(agentId)}: ${state.n8nLiveProbeResults[agentId].status}`, "success");
  } catch (error) {
    state.n8nLiveProbeResults = {
      ...state.n8nLiveProbeResults,
      [agentId]: { status: "failed", detail: compactError(error.message) },
    };
    renderAgentOperatingModelPanel();
    renderChatContractBadges();
    showToast("Live probe failed", `${agentDisplayName(agentId)}: ${compactError(error.message)}`, "error");
  }
}

function showAgentUatPayload(agentId) {
  if (!agentId) return;
  const envelope = buildUatEnvelope(agentId);
  state.n8nContractTestResult = {
    agent_id: agentId,
    agent_name: agentDisplayName(agentId),
    status: hasAgentWebhook(agentId) ? "webhook configured" : "fixture ready",
    webhook_env_var: {
      actor_twin: "N8N_ACTOR_TWIN_WEBHOOK_URL",
      knowledge_fabric_agent: "N8N_KNOWLEDGE_FABRIC_WEBHOOK_URL",
      agentic_butler: "N8N_AGENTIC_BUTLER_WEBHOOK_URL",
    }[agentId] || "N8N_WEBHOOK_URL",
    payload: envelope,
  };
  renderAgentOperatingModelPanel();
  showToast("UAT payload ready", agentDisplayName(agentId), "success");
}

function buildUatEnvelope(agentId) {
  if (agentId === "agentic_butler") {
    return buildAgentContractEnvelope(
      "agentic_butler",
      "activate_skill",
      "Prepare my day plan and pause before sending any email or meeting invite.",
      {
        skill_id: "project-management-support-steering",
        skill_name: "Project Management Support & Steering",
        manual_trigger: true,
        email_export: "Public-safe sample email export.",
        calendar_export: "Public-safe sample calendar export.",
        teams_export: "Public-safe sample Teams export.",
        knowledge_context: "Public-safe KPI and decision context.",
      },
      {
        actor_checkpoint_policy: "consult_actor_twin_before_prioritization_and_before_human_gates",
        skill_orchestrator: "internal_component",
        allowed_outputs: ["daily_plan", "todo_table", "approval_queue"],
      },
    );
  }
  if (agentId === "knowledge_fabric_agent") {
    return buildAgentContractEnvelope(
      "knowledge_fabric_agent",
      "ingest_concept",
      "Create a pending OKF concept from this public-safe source context.",
      {
        source_type: "transcript",
        title: "Public-safe UAT source note",
        content: "Public-safe source context for OKF ingest UAT.",
        target_state: "pending_review",
      },
      {
        okf_namespace: "concepts/florian/uat",
        allowed_outputs: ["markdown", "yaml_frontmatter", "graph_candidate_edges"],
        vector_policy: "do_not_refresh_without_approved_storage",
      },
    );
  }
  return buildAgentContractEnvelope(
    "actor_twin",
    "answer_question",
    "Which approved context should I use for a client alignment meeting?",
    { mode: "grounded_answer" },
    {
      okf_refs: ["concepts/florian/example/approved-client-context.md"],
      graph_refs: ["node:client-alignment"],
      retrieval_policy: "approved_first_include_pending_as_draft",
    },
  );
}

async function prepareKnowledgeFabricDryRun(operation) {
  state.knowledgeFabricDryRunResult = null;
  renderAgentOperatingModelPanel();
  try {
    const result = await postJson("/api/agents/knowledge-fabric/dry-run", {
      operation,
      twin: state.activeTwin,
      source_text: $("#chatSkillKnowledge")?.value || "",
    });
    state.knowledgeFabricDryRunResult = result;
    renderAgentOperatingModelPanel();
    showToast("Knowledge Fabric payload prepared", `${operation} dry-run`, "success");
  } catch (error) {
    showToast("Knowledge Fabric dry-run failed", compactError(error.message), "error");
  }
}

function renderAgentInstructionRegistry() {
  const target = $("#agentInstructionList");
  const select = $("#agentInstructionSelect");
  if (!target || !select) return;
  const instructions = state.agentInstructions?.instructions || [];
  if (!instructions.length) {
    target.innerHTML = renderEmptyState("No agent instructions registered yet.");
    select.innerHTML = "";
    return;
  }
  select.innerHTML = instructions
    .map((item) => `<option value="${escapeHtml(item.id)}">${escapeHtml(item.agent || item.id)}</option>`)
    .join("");
  target.innerHTML = instructions
    .map((item) => {
      const hooks = (item.runtime_hooks || []).slice(0, 3).map((hook) => `<span>${escapeHtml(hook)}</span>`).join("");
      const parent = topLevelAgentName(item.parent_agent);
      const internal = item.component_scope === "internal" ? " · internal" : "";
      return `
        <article class="agent-instruction-row ${item.exists ? "" : "missing"}">
          <div>
            <span class="queue-kind">${escapeHtml(`${parent || item.group || "agent"}${internal}`)}</span>
            <strong>${escapeHtml(item.agent || item.id)}</strong>
            <p>${escapeHtml(item.description || "")}</p>
            <code>${escapeHtml(item.source || item.file || "")}</code>
          </div>
          <div class="agent-hook-list">${hooks || "<span>No runtime hook listed</span>"}</div>
        </article>
      `;
    })
    .join("");
  if (!select.value && instructions[0]) select.value = instructions[0].id;
}

function topLevelAgentName(agentId) {
  const agents = state.agentOperatingModel?.top_level_agents || [];
  const match = agents.find((agent) => agent.id === agentId);
  return match?.name || "";
}

async function loadSelectedAgentInstruction() {
  const select = $("#agentInstructionSelect");
  const output = $("#agentInstructionContent");
  const instructionId = select?.value;
  if (!instructionId || !output) return;
  setOutputStatus("#agentInstructionContent", "loading", "Loading instruction", instructionId);
  try {
    const result = await getJson(`/api/agents/system-instructions/${encodeURIComponent(instructionId)}`);
    const instruction = result.instruction || {};
    output.className = "output compact-output";
    output.textContent = [
      `${instruction.agent || instruction.id || instructionId}`,
      `${instruction.source || ""}`,
      "",
      result.content || "",
    ].join("\n");
  } catch (error) {
    setOutputStatus("#agentInstructionContent", "error", "Instruction unavailable", error.message);
  }
}

function renderSkillCatalog() {
  const target = $("#skillCatalog");
  if (!state.skills.length) {
    target.innerHTML = renderEmptyState("No skills shaped yet.", "Shape first skill", "openSkills");
    renderSkillsCockpit();
    return;
  }
  const skills = state.skills.filter((skill) => state.skillStatusFilter === "all" || skill.status === state.skillStatusFilter);
  if (!skills.length) {
    target.innerHTML = renderEmptyState("No skills match this filter.");
    renderSkillsCockpit();
    return;
  }
  target.innerHTML = skills
    .map(
      (skill) => `
        <article class="skill-tile ${dashboardPriorityClass("skill", skill.status)} ${skill.skill_id === state.selectedSkillId ? "selected" : ""}">
          <div class="skill-tile-main">
            <div class="skill-tile-meta">
              <span class="queue-kind">${escapeHtml(skill.status || "skill")}</span>
              <span>${escapeHtml(skill.risk_class || "risk n/a")}</span>
              <span>v${escapeHtml(skill.version || "-")}</span>
            </div>
            <h3>${escapeHtml(skill.name)}</h3>
            <p>${escapeHtml(skill.description || "")}</p>
            <code>${escapeHtml(skill.folder || "")}</code>
          </div>
          <div class="skill-tile-actions">
            <button class="secondary small skill-select" type="button" data-id="${escapeHtml(skill.skill_id)}">Select</button>
            ${["rejected", "deprecated"].includes(skill.status)
              ? `<button class="danger small skill-archive" type="button" data-id="${escapeHtml(skill.skill_id)}">Archive</button>`
              : ""}
          </div>
        </article>
      `,
    )
    .join("");
  target.querySelectorAll(".skill-select").forEach((button) => {
    button.addEventListener("click", () => selectSkill(button.dataset.id));
  });
  target.querySelectorAll(".skill-archive").forEach((button) => {
    button.addEventListener("click", () => archiveSkill(button.dataset.id));
  });
}

function renderSkillsCockpit() {
  const target = $("#skillsCockpit");
  if (!target) return;
  const statusCounts = state.skills.reduce((acc, skill) => {
    const key = skill.status || "unknown";
    acc[key] = (acc[key] || 0) + 1;
    return acc;
  }, {});
  const approved = statusCounts.approved || 0;
  const pending = statusCounts.pending_approval || 0;
  const activeRuns = state.skillRuns.length;
  const correctiveRuns = state.skillRuns.filter((run) => ["needs_rework", "wrong_priority", "missing_context", "rejected"].includes(run.review_state)).length;
  const selected = state.skills.find((skill) => skill.skill_id === state.selectedSkillId);
  const drafts = (statusCounts.draft || 0) + (statusCounts.elicited || 0) + (statusCounts.decomposed || 0);
  const latestRun = state.skillRuns[0] || null;
  const pendingRefinements = state.skillRefinements.filter((item) => item.status === "pending_approval").length;
  const lifecycle = [
    {
      id: "shape",
      number: "01",
      title: "Shape",
      action: "focusSkillShape",
      metric: drafts,
      state: drafts ? "attention" : "ready",
      detail: "Capture triggers, inputs, outputs, boundaries, examples, and quality criteria.",
      hint: "Creates a SkillSpec; never approves automatically.",
    },
    {
      id: "approve",
      number: "02",
      title: "Approve",
      action: "focusSkillApproval",
      metric: pending,
      state: pending ? "attention" : "ready",
      detail: "Review generated agent configs, risk class, tool boundaries, and package lint.",
      hint: selected ? `Selected: ${selected.status || "unknown"}` : "Select a skill to inspect the gate.",
    },
    {
      id: "test",
      number: "03",
      title: "Test",
      action: "focusSkillRun",
      metric: activeRuns,
      state: approved ? "ready" : "blocked",
      detail: "Run approved skills with exported source context and Actor Twin steering.",
      hint: latestRun ? `Latest run: ${latestRun.review_state || latestRun.status || "unreviewed"}` : "Run history starts after first execution.",
    },
    {
      id: "refine",
      number: "04",
      title: "Refine",
      action: "focusSkillImprove",
      metric: pendingRefinements || correctiveRuns,
      state: pendingRefinements || correctiveRuns ? "attention" : "ready",
      detail: "Use run reviews and critique evidence to propose bounded version changes.",
      hint: `${pendingRefinements} proposal${pendingRefinements === 1 ? "" : "s"} pending review.`,
    },
  ];
  target.innerHTML = `
    <article class="cockpit-overview skills-overview">
      <div class="skill-cockpit-hero">
        <div>
          <span class="badge">Skill Cockpit</span>
          <h2>${escapeHtml(selected?.name || "Shape, approve, test, and refine skills")}</h2>
          <p>${escapeHtml(selected?.description || "Skills are reusable agentic behaviors. Human approval keeps generated versions out of active runtime until reviewed.")}</p>
        </div>
        <button class="secondary small" type="button" data-cockpit-action="openChat">Run from workspace</button>
      </div>
      <div class="skill-lifecycle-board" aria-label="Skill lifecycle">
        ${lifecycle.map((stage) => `
          <button class="skill-lifecycle-card ${escapeHtml(stage.state)} ${escapeHtml(stage.id)}" type="button" data-cockpit-action="${escapeHtml(stage.action)}">
            <span>${escapeHtml(stage.number)} · ${escapeHtml(stage.title)}</span>
            <strong>${escapeHtml(stage.metric)}</strong>
            <p>${escapeHtml(stage.detail)}</p>
            <small>${escapeHtml(stage.hint)}</small>
          </button>
        `).join("")}
      </div>
      <div class="cockpit-overview-grid skill-cockpit-kpis">
        <span class="${approved ? "ready" : ""}"><strong>${escapeHtml(approved)}</strong> approved</span>
        <span class="${pending ? "attention" : ""}"><strong>${escapeHtml(pending)}</strong> pending approval</span>
        <span><strong>${escapeHtml(activeRuns)}</strong> runs</span>
        <span class="${correctiveRuns ? "attention" : "ready"}"><strong>${escapeHtml(correctiveRuns)}</strong> need refinement</span>
      </div>
    </article>
  `;
}

async function archiveSkill(skillId) {
  if (!skillId) return;
  const confirmed = await requestDecision({
    eyebrow: "Skill archive",
    title: "Archive this skill?",
    body: "Rejected or deprecated skill versions leave the active catalog but remain available in local files and logs.",
    confirmLabel: "Archive skill",
    danger: true,
  });
  if (!confirmed) return;
  try {
    await postJson("/api/skills/archive", {
      skill_id: skillId,
      rationale: "Archived from Skills UI cleanup action.",
      actor: "local-user",
    });
    await safeRefreshSkills();
    await safeRefreshReviewDashboard();
    setOutputStatus("#skillResult", "success", "Skill archived", skillId);
    showToast("Skill archived", skillId, "success");
  } catch (error) {
    setOutputStatus("#skillResult", "error", "Archive failed", error.message);
    showToast("Archive failed", error.message, "error");
  }
}

function renderAppliedSkillsSelector() {
  const list = $("#appliedSkillsList");
  const summary = $("#appliedSkillsSummary");
  const approved = state.skills.filter((skill) => skill.status === "approved");
  const approvedIds = new Set(approved.map((skill) => skill.skill_id));
  state.appliedChatSkillIds = state.appliedChatSkillIds.filter((id) => approvedIds.has(id));
  state.activeChatSkillId = state.appliedChatSkillIds[0] || N8N_CHAT_MODE;
  if (!approved.length) {
    list.innerHTML = `<p class="muted-inline">No approved skills yet.</p>`;
  } else {
    list.innerHTML = approved
      .map((skill) => `
        <label class="skill-check">
          <input type="checkbox" class="applied-skill-filter" value="${escapeHtml(skill.skill_id)}" ${state.appliedChatSkillIds.includes(skill.skill_id) ? "checked" : ""} />
          <span>
            <strong>${escapeHtml(skill.name)}</strong>
            <small>${escapeHtml(skill.risk_class || "risk n/a")} · ${escapeHtml(skill.status || "-")}</small>
          </span>
        </label>
      `)
      .join("");
  }
  if (summary) {
    summary.textContent = state.appliedChatSkillIds.length
      ? `Applied skills: ${state.appliedChatSkillIds.length}`
      : "Applied skills: none";
  }
  renderChatSkillMode();
}

function renderChatSkillMode() {
  const applied = state.skills.filter((skill) => state.appliedChatSkillIds.includes(skill.skill_id));
  const isSkillMode = Boolean(applied.length);
  if (!["source_context", "skill_activation"].includes(state.activeChatInteractionMode)) $("#chatSkillContext").open = false;
  $("#chatSkillContext").hidden = false;
  $("#chatSkillContext").classList.toggle("hidden", false);
  $("#n8nAgentPanel").hidden = true;
  const modeSelect = $("#chatInteractionModeSelect");
  if (modeSelect) modeSelect.value = state.activeChatInteractionMode || "actor_twin";
  const n8nLink = $("#n8nAgentLink");
  if (n8nLink) {
    n8nLink.href = runtimeConfig.n8nChatWebhookUrl || "#";
    n8nLink.hidden = !runtimeConfig.n8nChatWebhookUrl;
  }
  setChatSkillStatus(
    `${chatInteractionModeLabel()} · governed pipeline · ${state.riskPosture} posture${applied.length ? ` · ${applied.length} applied skill${applied.length === 1 ? "" : "s"}` : ""}${state.webSearchEnabled ? " · websearch on" : ""}${state.voiceAnswerEnabled ? " · voice on" : ""}`,
  );
  $("#queryInput").placeholder = chatInteractionPlaceholder();
  $("#chatForm button").textContent = chatInteractionSubmitLabel();
  $("#saveChatPresetBtn").disabled = !isSkillMode;
  $("#loadChatPresetBtn").disabled = !isSkillMode || !state.skillInputPresets.length;
  $("#updateChatPresetBtn").disabled = !isSkillMode || !state.skillInputPresets.length;
  $("#deleteChatPresetBtn").disabled = !isSkillMode || !state.skillInputPresets.length;
  $("#chatPresetName").disabled = !isSkillMode;
  $("#chatPresetSelect").disabled = !isSkillMode || !state.skillInputPresets.length;
  renderChatInputPresets();
  renderSkillRoutingPanel();
  renderChatContractBadges();
  renderSkillPreflight();
}

function chatInteractionModeLabel() {
  if (state.activeChatInteractionMode === "skill_activation") return "Agentic Butler skill activation";
  if (state.activeChatInteractionMode === "source_context") return "Knowledge Fabric source intake";
  return "Actor Twin answer mode";
}

function chatInteractionPlaceholder() {
  if (state.activeChatInteractionMode === "skill_activation") return "Tell the Butler what approved skill outcome you need...";
  if (state.activeChatInteractionMode === "source_context") return "Describe what this source context should become...";
  return "Ask the Actor Twin...";
}

function chatInteractionSubmitLabel() {
  if (state.activeChatInteractionMode === "skill_activation") return "Activate";
  if (state.activeChatInteractionMode === "source_context") return "Add";
  return "Ask";
}

function renderSkillRoutingPanel() {
  const applied = state.skills.filter((skill) => state.appliedChatSkillIds.includes(skill.skill_id));
  const active = state.twins.find((twin) => twin.twin_id === state.activeTwin);
  const switchWarning = recentTwinSwitchWarning();
  const agentId = state.activeChatInteractionMode === "skill_activation"
    ? "agentic_butler"
    : state.activeChatInteractionMode === "source_context"
      ? "knowledge_fabric_agent"
      : "actor_twin";
  const configured = hasAgentWebhook(agentId);
  const content = `
      <strong>Actor pipeline</strong>
      <span>${escapeHtml(active?.display_name || state.activeTwin)} · ${escapeHtml(state.riskPosture)} posture · ${escapeHtml(chatInteractionModeLabel())} · ${escapeHtml(configured ? "n8n configured" : "fixture fallback")}</span>
      <p>${escapeHtml(state.webSearchEnabled ? "Websearch requested." : "Websearch off.")} ${escapeHtml(state.voiceAnswerEnabled ? "Voice playback on." : "Voice playback off.")} ${escapeHtml(applied.length ? `${applied.length} approved skill layer${applied.length === 1 ? "" : "s"} selected.` : "No approved skill layer selected.")}</p>
      ${switchWarning ? `<p class="warning-copy">${escapeHtml(switchWarning)}</p>` : ""}
    `;
  const chatPanel = $("#chatSkillRouting");
  if (chatPanel) chatPanel.innerHTML = content;
  const runPanel = $("#skillRunRouting");
  if (runPanel) runPanel.innerHTML = content;
}

function renderSkillPreflight() {
  const target = $("#chatSkillPreflight");
  if (!target) return;
  const selected = state.skills.find((skill) => skill.skill_id === state.activeChatSkillId);
  const active = state.twins.find((twin) => twin.twin_id === state.activeTwin);
  if (!selected) {
    target.innerHTML = "";
    return;
  }
  const sourceInput = {
    email_input: $("#chatSkillEmail").value,
    calendar_input: $("#chatSkillCalendar").value,
    teams_input: $("#chatSkillTeams").value,
    knowledge_context: $("#chatSkillKnowledge").value,
  };
  const readiness = sourceReadiness(sourceInput);
  const request = $("#queryInput").value.trim();
  const decisionPrinciples = active?.decision_principles || "prioritize deadlines, decisions, response time, and stakeholder urgency";
  const twinQuestion = readiness.missing.length
    ? `Before running, ${active?.display_name || state.activeTwin} would ask whether ${readiness.missing.join(", ")} context is intentionally empty.`
    : `${active?.display_name || state.activeTwin} has enough exported context for a first pass.`;
  target.innerHTML = `
    <div>
      <span class="badge">Twin preflight</span>
      <strong>${escapeHtml(twinQuestion)}</strong>
      <p>${escapeHtml(selected.name)} will use ${escapeHtml(readiness.present.join(", ") || "manual request only")} and steer with: ${escapeHtml(decisionPrinciples)}</p>
    </div>
    <div class="source-quality ${escapeHtml(readiness.level)}">
      <strong>${escapeHtml(readiness.label)}</strong>
      <span>${escapeHtml(readiness.detail)}</span>
    </div>
    <div class="preflight-grid">
      <span>${escapeHtml(readiness.readyCount)} source blocks ready</span>
      <span>${escapeHtml(readiness.missing.length)} source blocks open</span>
      <span>${escapeHtml(request ? "request captured" : "request still open")}</span>
    </div>
    ${readiness.followUps.length ? renderPreflightFollowUps(readiness.followUps, "chat") : ""}
  `;
  bindPreflightFollowUps(target);
}

async function ensureN8nChat() {
  const status = $("#n8nChatStatus");
  const mount = $("#n8nChatMount");
  const webhookUrl = runtimeConfig.n8nChatWebhookUrl || "";
  if (!runtimeConfig.n8nChatEnabled) {
    if (status) status.textContent = "n8n chat is disabled in runtime config.";
    return;
  }
  if (!webhookUrl) {
    if (status) status.textContent = "n8n webhook URL is missing in runtime config.";
    return;
  }
  if (state.n8nChatLoaded || state.n8nChatLoading) return;
  state.n8nChatLoading = true;
  if (status) status.textContent = "Loading n8n chat...";
  try {
    ensureStylesheet("n8n-chat-style", N8N_CHAT_CSS_URL);
    const module = await import(N8N_CHAT_MODULE_URL);
    mount.innerHTML = "";
    module.createChat({
      webhookUrl,
      target: "#n8nChatMount",
      mode: "fullscreen",
      showWelcomeScreen: false,
      loadPreviousSession: true,
      metadata: {
        source: "meids-intellectual-twin",
        activeTwin: state.activeTwin,
      },
      initialMessages: [
        "Hi, I'm at your Service :).",
        "Send the task or context you want this workflow to process.",
      ],
      i18n: {
        en: {
          title: "n8n agent",
          subtitle: "External workflow trigger",
          inputPlaceholder: "Trigger the n8n agent...",
        },
      },
    });
    state.n8nChatLoaded = true;
    if (status) status.textContent = "n8n agent connected.";
  } catch (error) {
    if (status) status.textContent = `n8n chat failed to load: ${error.message}`;
    showToast("n8n chat unavailable", error.message, "error");
  } finally {
    state.n8nChatLoading = false;
  }
}

async function askTwinViaN8n(query) {
  const webhookUrl = runtimeConfig.n8nChatWebhookUrl || "";
  if (!webhookUrl) throw new Error("n8n webhook URL is missing in runtime config.");
  const appliedSkills = state.skills
    .filter((skill) => state.appliedChatSkillIds.includes(skill.skill_id))
    .map((skill) => ({
      skill_id: skill.skill_id,
      name: skill.name,
      risk_class: skill.risk_class || "",
      status: skill.status || "",
      description: skill.description || "",
    }));
  const payload = {
    action: "sendMessage",
    sessionId: state.n8nSessionId,
    chatInput: query,
    metadata: {
      source: "meids-intellectual-twin",
      activeTwin: state.activeTwin,
      riskPosture: state.riskPosture,
      websearch: state.webSearchEnabled,
      retrievalMode: $("#retrievalModeSelect")?.value || "keyword",
      conceptTypes: selectedConceptTypes(),
      appliedSkills,
      sourceContext: {
        email_input: $("#chatSkillEmail")?.value || "",
        calendar_input: $("#chatSkillCalendar")?.value || "",
        teams_input: $("#chatSkillTeams")?.value || "",
        knowledge_context: $("#chatSkillKnowledge")?.value || "",
      },
    },
  };
  const response = await fetch(webhookUrl, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  const raw = await response.text();
  if (!response.ok) {
    throw new Error(raw || `n8n returned ${response.status}`);
  }
  let data = raw;
  try {
    data = raw ? JSON.parse(raw) : {};
  } catch {
    data = raw;
  }
  return {
    answer: extractN8nAnswer(data),
    metadata: {
      retrieval_mode: "n8n",
      confidence: 0,
      sources: [],
      n8n: {
        sessionId: state.n8nSessionId,
        riskPosture: state.riskPosture,
        websearch: state.webSearchEnabled,
        appliedSkills: appliedSkills.map((skill) => skill.name),
      },
    },
  };
}

function extractN8nAnswer(data) {
  if (typeof data === "string") return data || "n8n workflow completed without text output.";
  if (Array.isArray(data)) {
    return data.map(extractN8nAnswer).filter(Boolean).join("\n\n") || "n8n workflow completed.";
  }
  if (!data || typeof data !== "object") return "n8n workflow completed.";
  return (
    data.output ||
    data.text ||
    data.answer ||
    data.response ||
    data.message ||
    data.data?.output ||
    data.data?.text ||
    data.data?.answer ||
    JSON.stringify(data, null, 2)
  );
}

function ensureStylesheet(id, href) {
  if (document.getElementById(id)) return;
  const link = document.createElement("link");
  link.id = id;
  link.rel = "stylesheet";
  link.href = href;
  document.head.appendChild(link);
}

function renderPreflightFollowUps(followUps, surface) {
  return `
    <div class="preflight-followups">
      ${followUps.map((item) => `
        <button class="preflight-followup-btn" type="button" data-target="${escapeHtml(sourceFieldTarget(item.key, surface))}">
          <strong>${escapeHtml(item.label)}</strong>
          <span>${escapeHtml(item.prompt)}</span>
        </button>
      `).join("")}
    </div>
  `;
}

function sourceFieldTarget(key, surface) {
  const prefix = surface === "skills" ? "skillRun" : "chatSkill";
  const targets = {
    email_input: `${prefix}Email`,
    calendar_input: `${prefix}Calendar`,
    teams_input: `${prefix}Teams`,
    knowledge_context: `${prefix}Knowledge`,
  };
  return targets[key] || `${prefix}Knowledge`;
}

function renderChatInputPresets() {
  const select = $("#chatPresetSelect");
  const current = select.value;
  select.innerHTML = [
    '<option value="">No saved preset</option>',
    ...state.skillInputPresets.map((preset) => `<option value="${escapeHtml(preset.preset_id)}">${escapeHtml(preset.name)}</option>`),
  ].join("");
  select.value = state.skillInputPresets.some((preset) => preset.preset_id === current) ? current : "";
  const isSkillMode = Boolean(state.appliedChatSkillIds.length);
  const hasPresets = Boolean(state.skillInputPresets.length);
  $("#loadChatPresetBtn").disabled = !isSkillMode || !hasPresets;
  $("#updateChatPresetBtn").disabled = !isSkillMode || !hasPresets;
  $("#deleteChatPresetBtn").disabled = !isSkillMode || !hasPresets;
  $("#chatPresetSelect").disabled = !isSkillMode || !hasPresets;
  const chipTarget = $("#chatPresetChips");
  chipTarget.innerHTML = state.skillInputPresets.slice(0, 5).map((preset) => {
    const lastUsed = preset.last_used_at ? ` · last used ${formatShortDate(preset.last_used_at)}` : "";
    return `<button class="preset-chip" type="button" data-preset-id="${escapeHtml(preset.preset_id)}">${escapeHtml(preset.name)}${escapeHtml(lastUsed)}</button>`;
  }).join("");
  chipTarget.querySelectorAll(".preset-chip").forEach((button) => {
    button.addEventListener("click", () => {
      $("#chatPresetSelect").value = button.dataset.presetId;
      loadChatInputPreset();
    });
  });
}

function sourceReadiness(inputs) {
  const sourceMap = [
    ["email_input", "Email", "Paste recent email threads or stakeholder asks."],
    ["calendar_input", "Calendar", "Paste calendar blockers, attendees, deadlines, or meeting context."],
    ["teams_input", "Teams", "Paste Teams messages or channel updates with decisions and blockers."],
    ["knowledge_context", "Knowledge", "Paste project notes, KPIs, prior documents, or decision logs."],
  ];
  const present = sourceMap.filter(([key]) => String(inputs[key] || "").trim()).map(([, label]) => label);
  const missingItems = sourceMap.filter(([key]) => !String(inputs[key] || "").trim());
  const missing = missingItems.map(([, label]) => label.toLowerCase());
  const followUps = missingItems.map(([key, label, prompt]) => ({ key, label, prompt }));
  const readyCount = present.length;
  let level = "low";
  let label = "Manual-only context";
  let detail = "The twin can run, but priorities may be weaker without exported work sources.";
  if (readyCount >= 3) {
    level = "high";
    label = "Strong source context";
    detail = "Enough exported context for a grounded first pass.";
  } else if (readyCount >= 1) {
    level = "medium";
    label = "Partial source context";
    detail = "Usable for a draft, with follow-up needed for missing streams.";
  }
  return { present, missing, followUps, readyCount, level, label, detail };
}

async function confirmSkillFollowUpGate(inputs, surface) {
  const readiness = sourceReadiness(inputs);
  if (readiness.readyCount > 0) return true;
  const prefix = surface === "chat"
    ? "The twin has only your chat request for this skill run."
    : "The twin has only your manual request for this skill run.";
  const followUpText = readiness.followUps.map((item) => `${item.label}: ${item.prompt}`).join("\n- ");
  return requestDecision({
    eyebrow: "Source preflight",
    title: "Continue without exported sources?",
    body: `${prefix}\n\nSuggested follow-up inputs:\n- ${followUpText}`,
    confirmLabel: "Continue",
  });
}

function bindPreflightFollowUps(root = document) {
  root.querySelectorAll(".preflight-followup-btn").forEach((button) => {
    button.addEventListener("click", () => {
      const target = $(`#${CSS.escape(button.dataset.target || "")}`);
      if (!target) return;
      target.scrollIntoView({ block: "center", behavior: "smooth" });
      target.focus();
    });
  });
}

function chatAgentContractStatuses() {
  const contracts = state.n8nAgentContracts?.contracts || [];
  const byAgent = new Map(contracts.map((contract) => [contract.agent_id, contract]));
  return ["actor_twin", "knowledge_fabric_agent", "agentic_butler"].map((agentId) => {
    const contract = byAgent.get(agentId) || {};
    const configured = hasAgentWebhook(agentId) || Boolean(contract.webhook_configured);
    const replayPassed = state.n8nAgentContracts?.replay_status === "passed" || contract.replay_status === "passed";
    const probe = state.n8nLiveProbeResults?.[agentId];
    return {
      agentId,
      label: agentDisplayName(agentId),
      state: probe?.status === "connected"
        ? "n8n connected"
        : configured
          ? "configured"
          : replayPassed
            ? "fixture ready"
            : "documented",
      configured,
      replayPassed,
      active: chatModeAgentId() === agentId,
    };
  });
}

function chatModeAgentId() {
  if (state.activeChatInteractionMode === "skill_activation") return "agentic_butler";
  if (state.activeChatInteractionMode === "source_context") return "knowledge_fabric_agent";
  return "actor_twin";
}

function renderChatContractBadges() {
  const target = $("#chatContractBadges");
  if (!target) return;
  target.innerHTML = chatAgentContractStatuses()
    .map((item) => `
      <span class="${item.active ? "active" : ""} ${item.configured ? "configured" : "fixture"}">
        <strong>${escapeHtml(item.label)}</strong>
        <small>${escapeHtml(item.state)}</small>
      </span>
    `)
    .join("");
}

function n8nAgentWebhooks() {
  return runtimeConfig.n8nAgentWebhooks || runtimeConfig.n8n_agent_webhooks || {};
}

function getAgentWebhook(agentId) {
  const webhooks = n8nAgentWebhooks();
  const direct = webhooks[agentId] || webhooks[agentId?.replaceAll("_", "-")];
  if (direct) return direct;
  if (agentId === "actor_twin") return runtimeConfig.n8nActorTwinWebhookUrl || runtimeConfig.n8nChatWebhookUrl || "";
  if (agentId === "agentic_butler") return runtimeConfig.n8nAgenticButlerWebhookUrl || "";
  if (agentId === "knowledge_fabric_agent") return runtimeConfig.n8nKnowledgeFabricWebhookUrl || "";
  return "";
}

function hasAgentWebhook(agentId) {
  return Boolean(getAgentWebhook(agentId));
}

function chatSourceContext() {
  return {
    email_input: $("#chatSkillEmail")?.value || "",
    calendar_input: $("#chatSkillCalendar")?.value || "",
    teams_input: $("#chatSkillTeams")?.value || "",
    knowledge_context: $("#chatSkillKnowledge")?.value || "",
  };
}

function graphPromotionDecision(edge = {}) {
  const reviewState = edge.review_state || "unreviewed";
  const relation = edge.relation_type || edge.edge_type || "";
  const edgeClass = graphEdgeClass(edge);
  if (reviewState === "accepted" || reviewState === "approved") {
    return {
      label: reviewState === "accepted" ? "accepted" : "approved",
      trust: "trusted",
      className: "approved",
      fixture: "contracts/okf/promotions/approve-edge-example.json",
      description: "Available to the Actor Twin for grounded retrieval and skill context.",
    };
  }
  if (reviewState === "rejected") {
    return {
      label: "rejected",
      trust: "excluded",
      className: "rejected",
      fixture: "contracts/okf/promotions/reject-edge-example.json",
      description: "Excluded from retrieval; retained only for audit and curator learning.",
    };
  }
  if (reviewState === "needs-rework") {
    return {
      label: "needs rework",
      trust: "cockpit only",
      className: "needs-rework",
      fixture: "contracts/okf/promotions/needs-rework-edge-example.json",
      description: "Requires stronger evidence or clearer relation wording before use.",
    };
  }
  if (String(edgeClass).includes("candidate") || String(relation).includes("candidate")) {
    return {
      label: "candidate",
      trust: "review required",
      className: "candidate",
      fixture: "contracts/okf/promotions/approve-edge-example.json",
      description: "Visible as a hypothesis; not trusted until a human promotion decision.",
    };
  }
  if (edgeClass === "explicit") {
    return {
      label: "explicit",
      trust: "source-backed",
      className: "approved",
      fixture: "contracts/okf/promotions/approve-edge-example.json",
      description: "Source-backed relation that can support grounded retrieval.",
    };
  }
  return {
    label: "inferred",
    trust: "use with attribution",
    className: "inferred",
    fixture: "contracts/okf/promotions/needs-rework-edge-example.json",
    description: "Useful for recall expansion; decisions should cite supporting nodes.",
  };
}

function renderGraphPromotionChips(edge = {}) {
  const decision = graphPromotionDecision(edge);
  const relation = edge.relation_type || edge.edge_type || "related";
  const edgeClass = graphEdgeClass(edge);
  return `
    <div class="graph-promotion-strip ${safeGraphClass(decision.className)}">
      <span class="graph-promotion-chip ${safeGraphClass(decision.className)}">${escapeHtml(decision.label)}</span>
      <span class="graph-promotion-chip trust">${escapeHtml(decision.trust)}</span>
      <span class="graph-promotion-chip">${escapeHtml(labelizeGraph(edgeClass))}</span>
      <span class="graph-promotion-chip">${escapeHtml(labelizeGraph(relation))}</span>
      <small>${escapeHtml(decision.description)}</small>
    </div>
  `;
}

function renderGraphPromotionFixtureLinks(edge = {}) {
  const decision = graphPromotionDecision(edge);
  const fixtures = [
    ["Approve fixture", "contracts/okf/promotions/approve-edge-example.json"],
    ["Needs rework fixture", "contracts/okf/promotions/needs-rework-edge-example.json"],
    ["Reject fixture", "contracts/okf/promotions/reject-edge-example.json"],
  ];
  return `
    <div class="graph-promotion-fixtures">
      <small>Promotion contract</small>
      ${fixtures.map(([label, path]) => `
        <a class="${path === decision.fixture ? "active" : ""}" href="${escapeHtml(githubBlobUrl(path))}" target="_blank" rel="noreferrer">${escapeHtml(label)}</a>
      `).join("")}
    </div>
  `;
}

function activePrincipal() {
  const twin = state.twins.find((item) => item.twin_id === state.activeTwin);
  return {
    twin_id: state.activeTwin || "florian",
    display_name: twin?.display_name || state.activeTwin || "Florian",
  };
}

function buildAgentContractEnvelope(agentId, intent, query, input = {}, context = {}, approval = null) {
  return {
    envelope_version: "0.1.0",
    request_id: `req_${agentId}_${Date.now().toString(36)}`,
    timestamp: new Date().toISOString(),
    agent_id: agentId,
    intent,
    principal: activePrincipal(),
    input: {
      query,
      ...input,
    },
    context: {
      source: "meids-chat",
      session_id: state.n8nSessionId,
      risk_posture: state.riskPosture,
      retrieval_mode: $("#retrievalModeSelect")?.value || "keyword",
      concept_types: selectedConceptTypes(),
      websearch: state.webSearchEnabled,
      ...context,
    },
    approval: approval || {
      required: false,
      reason: "No external write action requested at submission time.",
    },
  };
}

async function routeActorTwinFromChat(query) {
  const envelope = buildAgentContractEnvelope(
    "actor_twin",
    "answer_question",
    query,
    { mode: "grounded_answer" },
    {
      okf_refs: [],
      graph_refs: [],
      source_context: chatSourceContext(),
      retrieval_policy: "approved_first_include_pending_as_draft",
    },
  );
  return postAgentContractEnvelope("actor_twin", envelope, fallbackActorTwinResponse);
}

async function routeAgenticButlerFromChat(query) {
  const selected = state.skills.find((skill) => skill.skill_id === state.activeChatSkillId)
    || state.skills.find((skill) => state.appliedChatSkillIds.includes(skill.skill_id));
  if (!selected) throw new Error("Select one approved skill before activating Agentic Butler.");
  if (selected.status !== "approved") throw new Error("Agentic Butler can only activate approved skills.");
  const sourceContext = chatSourceContext();
  const envelope = buildAgentContractEnvelope(
    "agentic_butler",
    "activate_skill",
    query,
    {
      skill_id: selected.skill_id,
      skill_name: selected.name,
      manual_trigger: true,
      email_export: sourceContext.email_input,
      calendar_export: sourceContext.calendar_input,
      teams_export: sourceContext.teams_input,
      knowledge_context: sourceContext.knowledge_context,
    },
    {
      actor_checkpoint_policy: "consult_actor_twin_before_prioritization_and_before_human_gates",
      skill_orchestrator: "internal_component",
      allowed_outputs: ["daily_plan", "todo_table", "approval_queue"],
    },
  );
  return postAgentContractEnvelope("agentic_butler", envelope, fallbackAgenticButlerResponse);
}

async function routeKnowledgeFabricFromChat(query) {
  const sourceContext = chatSourceContext();
  const title = query.slice(0, 80) || "Chat source context";
  const envelope = buildAgentContractEnvelope(
    "knowledge_fabric_agent",
    "ingest_concept",
    query,
    {
      source_type: "chat_source_context",
      title,
      content: [sourceContext.email_input, sourceContext.calendar_input, sourceContext.teams_input, sourceContext.knowledge_context]
        .filter(Boolean)
        .join("\n\n")
        .slice(0, 12000),
      target_state: "pending_review",
    },
    {
      okf_namespace: `concepts/${state.activeTwin || "florian"}/inbox`,
      allowed_outputs: ["markdown", "yaml_frontmatter", "graph_candidate_edges"],
      vector_policy: "do_not_refresh_without_approved_storage",
    },
  );
  return postAgentContractEnvelope("knowledge_fabric_agent", envelope, fallbackKnowledgeFabricResponse);
}

async function postAgentContractEnvelope(agentId, envelope, fallbackFactory) {
  const webhookUrl = getAgentWebhook(agentId);
  if (!webhookUrl) return fallbackFactory(envelope, "fixture fallback");
  const body = isN8nChatWebhook(webhookUrl)
    ? {
        action: "sendMessage",
        sessionId: state.n8nSessionId,
        chatInput: envelope.input?.query || "",
        metadata: {
          source: "meids-contract-bridge",
          agent_id: agentId,
          contract_envelope: envelope,
        },
      }
    : envelope;
  const response = await fetch(webhookUrl, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  const raw = await response.text();
  if (!response.ok) throw new Error(raw || `${agentId} returned ${response.status}`);
  const data = parseMaybeJson(raw);
  return normalizeAgentContractResponse(agentId, data, envelope, "n8n connected");
}

function isN8nChatWebhook(url) {
  return /\/chat(?:$|[?#/])/i.test(String(url || ""));
}

function parseMaybeJson(raw) {
  try {
    return raw ? JSON.parse(raw) : {};
  } catch {
    return { output: { answer: raw } };
  }
}

function normalizeAgentContractResponse(agentId, data, envelope, runtime) {
  const response = data?.response || data?.data || data || {};
  const status = response.status || data?.status || "completed";
  return {
    agent_id: agentId,
    agent_name: agentDisplayName(agentId),
    runtime,
    trace_id: response.trace?.trace_id || response.trace_id || data?.trace_id || envelope.request_id,
    request: envelope,
    response: {
      envelope_version: response.envelope_version || envelope.envelope_version,
      request_id: response.request_id || envelope.request_id,
      agent_id: response.agent_id || agentId,
      status,
      output: response.output || data?.output || outputFromN8nData(data),
      approval: response.approval || data?.approval || null,
      trace: response.trace || data?.trace || { trace_id: response.trace_id || data?.trace_id || envelope.request_id, stored: false },
      error: response.error || data?.error || null,
    },
    answer: extractAgentAnswer(response.output || data?.output || data, status),
  };
}

function persistAgentTrace(result = {}) {
  const response = result.response || {};
  const trace = response.trace || {};
  const entry = {
    timestamp: new Date().toISOString(),
    twin: state.activeTwin || "",
    agent_id: result.agent_id || response.agent_id || "",
    agent_name: result.agent_name || agentDisplayName(result.agent_id || response.agent_id || ""),
    status: response.status || result.status || "",
    runtime: result.runtime || "",
    request_id: response.request_id || result.request?.request_id || "",
    trace_id: trace.trace_id || result.trace_id || "",
    approval_required: response.status === "approval_required" || Boolean(response.approval?.required),
  };
  try {
    const current = JSON.parse(window.localStorage.getItem(storageKeys.agentTraceLog) || "[]");
    const next = [entry, ...(Array.isArray(current) ? current : [])].slice(0, 50);
    window.localStorage.setItem(storageKeys.agentTraceLog, JSON.stringify(next));
    renderAgentTraceHistoryPanel();
  } catch (error) {
    console.warn("Agent trace persistence failed", error);
  }
}

function readAgentTraceLog() {
  try {
    const value = JSON.parse(window.localStorage.getItem(storageKeys.agentTraceLog) || "[]");
    return Array.isArray(value) ? value : [];
  } catch {
    return [];
  }
}

function clearAgentTraceHistory() {
  try {
    window.localStorage.removeItem(storageKeys.agentTraceLog);
  } catch (error) {
    console.warn("Agent trace clear failed", error);
  }
  renderAgentTraceHistoryPanel();
}

function renderAgentTraceHistoryPanel() {
  const target = $("#agentTraceHistoryPanel");
  if (!target) return;
  const traces = readAgentTraceLog();
  if (!traces.length) {
    target.innerHTML = '<p class="empty">No local agent handoffs yet.</p>';
    return;
  }
  target.innerHTML = traces.slice(0, 12).map((trace) => `
    <article class="agent-trace-row ${trace.approval_required ? "approval" : "completed"}">
      <div>
        <span class="badge">${escapeHtml(trace.approval_required ? "approval gate" : trace.status || "trace")}</span>
        <strong>${escapeHtml(trace.agent_name || agentDisplayName(trace.agent_id || ""))}</strong>
        <p>${escapeHtml(`${trace.runtime || "fixture/local"} · ${trace.twin || "active twin"} · ${formatShortDate(trace.timestamp)}`)}</p>
      </div>
      <div class="agent-trace-meta">
        <code>${escapeHtml(trace.trace_id || "trace pending")}</code>
        <small>${escapeHtml(trace.request_id || "")}</small>
      </div>
    </article>
  `).join("");
}

function outputFromN8nData(data) {
  if (typeof data === "string") return { answer: data };
  if (data?.answer || data?.text || data?.message) return { answer: data.answer || data.text || data.message };
  return data && typeof data === "object" ? data : {};
}

function extractAgentAnswer(output, status = "completed") {
  if (status === "approval_required") return "Human approval is required before this action can continue.";
  if (typeof output === "string") return output;
  if (!output || typeof output !== "object") return "Agent completed.";
  return output.answer || output.summary || output.concept_path || "Agent completed.";
}

function agentDisplayName(agentId) {
  return {
    actor_twin: "Actor Twin",
    knowledge_fabric_agent: "Knowledge Fabric Agent",
    agentic_butler: "Agentic Butler",
  }[agentId] || agentId || "Agent";
}

function fallbackActorTwinResponse(envelope, runtime) {
  const query = envelope.input?.query || "";
  return normalizeAgentContractResponse("actor_twin", {
    status: "completed",
    output: {
      answer: `Actor Twin fixture response: ${query || "Ask received"}. Use approved OKF context first; include drafts only as unvalidated hypotheses.`,
      confidence: 0.78,
      citations: [],
    },
    trace: { trace_id: `trace_${envelope.request_id}`, used_agents: ["knowledge_fabric_agent"], stored: false },
  }, envelope, runtime);
}

function fallbackAgenticButlerResponse(envelope, runtime) {
  const proposesExternalAction = /send|mail|email|invite|meeting|schedule/i.test(envelope.input?.query || "");
  if (proposesExternalAction) {
    return normalizeAgentContractResponse("agentic_butler", {
      status: "approval_required",
      approval: {
        required: true,
        gate: "requires_human_action",
        summary: "The skill request may create or send an external action.",
        proposed_action: "Prepare the output, then pause before sending email or creating meetings.",
      },
      trace: { trace_id: `trace_${envelope.request_id}`, used_agents: ["skill_orchestrator", "actor_twin"], stored: false },
    }, envelope, runtime);
  }
  return normalizeAgentContractResponse("agentic_butler", {
    status: "completed",
    output: {
      summary: "Daily plan generated from exported source context.",
      todos: [
        {
          what: "Prepare alignment brief",
          how: "Summarize source context, open decisions, and stakeholder urgency.",
          why: "Reduce decision latency and improve meeting quality.",
          whom: "Client delivery / internal workstream",
          priority: "high",
        },
      ],
      approval_queue: [],
    },
    trace: { trace_id: `trace_${envelope.request_id}`, used_agents: ["skill_orchestrator", "actor_twin"], stored: false },
  }, envelope, runtime);
}

function fallbackKnowledgeFabricResponse(envelope, runtime) {
  const slug = slugify(envelope.input?.title || "chat-source-context");
  return normalizeAgentContractResponse("knowledge_fabric_agent", {
    status: "completed",
    output: {
      concept_path: `concepts/${state.activeTwin || "florian"}/inbox/${new Date().toISOString().slice(0, 10)}-${slug}.md`,
      review_state: "pending_review",
      candidate_edges: [
        {
          source: `concept:${slug}`,
          target: "cluster:inbox",
          relation_type: "candidate_member_of_cluster",
          confidence: 0.58,
        },
      ],
    },
    trace: { trace_id: `trace_${envelope.request_id}`, used_agents: ["graph_curator"], stored: false },
  }, envelope, runtime);
}

function slugify(value) {
  return String(value || "item")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80) || "item";
}

function agentContractResponseText(result = {}) {
  const response = result.response || {};
  const output = response.output || {};
  if (response.status === "approval_required") {
    return response.approval?.summary || "Human approval is required before this action can continue.";
  }
  return result.answer || output.answer || output.summary || output.concept_path || `${result.agent_name || "Agent"} completed.`;
}

async function saveChatInputPreset() {
  if (!state.activeChatSkillId) {
    setChatSkillStatus("Select an approved skill before saving a preset.", "error");
    return;
  }
  const name = $("#chatPresetName").value.trim();
  if (!name) {
    setChatSkillStatus("Add a preset name first.", "error");
    return;
  }
  try {
    const result = await postJson("/api/skills/input-presets", {
      name,
      skill_id: state.activeChatSkillId,
      manual_request: $("#queryInput").value,
      email_input: $("#chatSkillEmail").value,
      calendar_input: $("#chatSkillCalendar").value,
      teams_input: $("#chatSkillTeams").value,
      knowledge_context: $("#chatSkillKnowledge").value,
      actor: "local-user",
    });
    $("#chatPresetName").value = "";
    await safeRefreshSkillInputPresets();
    $("#chatPresetSelect").value = result.preset?.preset_id || "";
    setChatSkillStatus(`Preset saved: ${name}`, "success");
    showToast("Preset saved", name, "success");
  } catch (error) {
    setChatSkillStatus(`Preset save failed: ${error.message}`, "error");
    showToast("Preset save failed", error.message, "error");
  }
}

function loadChatInputPreset() {
  const preset = state.skillInputPresets.find((item) => item.preset_id === $("#chatPresetSelect").value);
  if (!preset) return;
  const payload = preset.payload || {};
  $("#queryInput").value = payload.manual_request || "";
  $("#chatSkillEmail").value = payload.email_input || "";
  $("#chatSkillCalendar").value = payload.calendar_input || "";
  $("#chatSkillTeams").value = payload.teams_input || "";
  $("#chatSkillKnowledge").value = payload.knowledge_context || "";
  $("#chatPresetName").value = preset.name || "";
  renderSkillPreflight();
  postJson("/api/skills/input-presets/touch", { preset_id: preset.preset_id, actor: "local-user" })
    .then(safeRefreshSkillInputPresets)
    .catch((error) => console.warn("Preset last-used update failed", error));
}

async function updateChatInputPreset() {
  const presetId = $("#chatPresetSelect").value;
  if (!presetId || !state.activeChatSkillId) return;
  const name = $("#chatPresetName").value.trim() || state.skillInputPresets.find((item) => item.preset_id === presetId)?.name || "";
  if (!name) {
    setChatSkillStatus("Add a preset name first.", "error");
    return;
  }
  try {
    await postJson("/api/skills/input-presets/update", {
      preset_id: presetId,
      name,
      skill_id: state.activeChatSkillId,
      manual_request: $("#queryInput").value,
      email_input: $("#chatSkillEmail").value,
      calendar_input: $("#chatSkillCalendar").value,
      teams_input: $("#chatSkillTeams").value,
      knowledge_context: $("#chatSkillKnowledge").value,
      actor: "local-user",
    });
    await safeRefreshSkillInputPresets();
    $("#chatPresetSelect").value = presetId;
    setChatSkillStatus(`Preset updated: ${name}`, "success");
    showToast("Preset updated", name, "success");
  } catch (error) {
    setChatSkillStatus(`Preset update failed: ${error.message}`, "error");
    showToast("Preset update failed", error.message, "error");
  }
}

async function deleteChatInputPreset() {
  const presetId = $("#chatPresetSelect").value;
  const preset = state.skillInputPresets.find((item) => item.preset_id === presetId);
  if (!preset) return;
  const confirmed = await requestDecision({
    eyebrow: "Preset cleanup",
    title: `Delete preset "${preset.name}"?`,
    body: "This removes the reusable source bundle from the active skill workspace.",
    confirmLabel: "Delete preset",
    danger: true,
  });
  if (!confirmed) return;
  try {
    await deleteJson("/api/skills/input-presets", {
      preset_id: presetId,
      actor: "local-user",
    });
    await safeRefreshSkillInputPresets();
    setChatSkillStatus(`Preset deleted: ${preset.name}`, "success");
    showToast("Preset deleted", preset.name, "success");
  } catch (error) {
    setChatSkillStatus(`Preset delete failed: ${error.message}`, "error");
    showToast("Preset delete failed", error.message, "error");
  }
}

async function selectSkill(skillId) {
  state.selectedSkillId = skillId;
  renderSkillCatalog();
  renderSkillsCockpit();
  renderSkillRoutingPanel();
  $("#skillDetail").innerHTML = renderLoadingState("Loading skill detail");
  try {
    const detail = await getJson(`/api/skills/detail?skill_id=${encodeURIComponent(skillId)}`);
    renderSkillDetail(detail);
  } catch (error) {
    $("#skillDetail").innerHTML = renderErrorState("Could not load skill", error.message);
  }
}

function renderSkillDetail(detail) {
  const spec = detail.spec || {};
  const config = detail.config || {};
  const lint = detail.lint || {};
  const status = config.status || state.skills.find((skill) => skill.skill_id === detail.skill_id)?.status || "elicited";
  $("#skillDetail").innerHTML = `
    <article class="activity-row queue-card skill-detail-card ${dashboardPriorityClass("skill", status)}">
      <div class="queue-card-head">
        <span class="queue-kind">${escapeHtml(status)}</span>
        ${renderQueueMeta([`risk ${spec.risk_class || "-"}`, lint.valid ? "lint valid" : "lint attention"])}
      </div>
      <h3>${escapeHtml(spec.name || detail.skill_id)}</h3>
      <p>${escapeHtml(spec.description || "")}</p>
      <dl>
        ${detailRow("Skill ID", detail.skill_id)}
        ${detailRow("Folder", detail.folder)}
        ${detailRow("Triggers", (spec.triggers || []).join(", "))}
        ${detailRow("Human required", spec.decision_boundaries?.requires_human?.join(", ") || "-")}
      </dl>
    </article>
    <article class="activity-row queue-card review">
      <div class="queue-card-head">
        <span class="queue-kind">Elicitation</span>
        ${renderQueueMeta([`${(spec.elicitation_questions || []).length} question${(spec.elicitation_questions || []).length === 1 ? "" : "s"}`])}
      </div>
      <h3>Elicitation Questions</h3>
      ${(spec.elicitation_questions || []).map((item) => `<p>- ${escapeHtml(item)}</p>`).join("") || '<p class="empty">No questions stored.</p>'}
    </article>
    ${renderSkillAgentGraph(config)}
    <article class="activity-row queue-card ${lint.valid ? "ready" : "needs-action"}">
      <div class="queue-card-head">
        <span class="queue-kind">Package lint</span>
        ${renderQueueMeta([lint.valid ? "valid" : "needs attention"])}
      </div>
      <h3>Lint</h3>
      ${lint.valid ? '<p>Skill package is valid.</p>' : (lint.errors || []).map((item) => `<p>- ${escapeHtml(item)}</p>`).join("")}
    </article>
  `;
  $("#decomposeSkillBtn").disabled = !["elicited", "decomposed", "pending_approval"].includes(status);
  const canApprove = status === "pending_approval";
  $("#approveSkillBtn").disabled = !canApprove;
  $("#rejectSkillBtn").disabled = !canApprove;
  $("#runSkillBtn").disabled = status !== "approved";
  $("#skillApprovalReadiness").textContent = canApprove
    ? "This skill is pending approval. Human approval is required before active use."
    : `Selected skill status: ${status}`;
  $("#skillRunReadiness").textContent = status === "approved"
    ? "This skill is approved. Paste exported source text and run it."
    : `Selected skill status: ${status}. Approval is required before running.`;
}

function renderSkillAgentGraph(config) {
  const orchestrator = config.orchestrator || {};
  const taskAgents = Array.isArray(config.task_agents) ? config.task_agents : [];
  const checkpoints = Array.isArray(orchestrator.actor_checkpoints) ? orchestrator.actor_checkpoints : [];
  const actor = config.actor_agent || {};
  return `
    <article class="activity-row queue-card skill-agent-graph">
      <div class="queue-card-head">
        <span class="queue-kind">Agent graph</span>
        ${renderQueueMeta([`${taskAgents.length} task agent${taskAgents.length === 1 ? "" : "s"}`, `${checkpoints.length} actor checkpoint${checkpoints.length === 1 ? "" : "s"}`])}
      </div>
      <div class="agent-graph-flow" aria-label="Skill agent graph">
        <div class="agent-node orchestrator">
          <span>Orchestrator</span>
          <strong>${escapeHtml(orchestrator.mode || "manager")}</strong>
          <small>${escapeHtml(orchestrator.model || "model n/a")} · max ${escapeHtml(orchestrator.max_steps || "-")} steps</small>
        </div>
        <div class="agent-node actor">
          <span>Actor Twin</span>
          <strong>${escapeHtml(actor.persona_ref || state.activeTwin)}</strong>
          <small>${escapeHtml(checkpoints.join(", ") || "checkpoint on demand")}</small>
        </div>
        ${taskAgents.length
          ? taskAgents.map((agent) => `
              <div class="agent-node task">
                <span>Task agent</span>
                <strong>${escapeHtml(agent.name || "task-agent")}</strong>
                <small>${escapeHtml((agent.tools || []).join(", ") || agent.instructions_ref || "no tools")}</small>
              </div>
            `).join("")
          : '<p class="empty">No decomposed task agents stored yet.</p>'}
      </div>
    </article>
  `;
}

async function elicitSkill() {
  const description = $("#skillDescriptionInput").value.trim();
  if (!description) {
    $("#skillResult").textContent = "Describe the skill first.";
    return;
  }
  $("#skillResult").textContent = "Creating SkillSpec...";
  try {
    const result = await postJson("/api/skills/elicit", {
      description,
      name_hint: $("#skillNameHint").value.trim() || null,
      twin: state.activeTwin,
      actor: "local-user",
    });
    $("#skillResult").textContent = formatSkillActionResult(result);
    await safeRefreshSkills();
    await safeRefreshReviewDashboard();
    await selectSkill(result.skill.skill_id);
  } catch (error) {
    $("#skillResult").textContent = `Skill elicitation failed: ${error.message}`;
  }
}

async function decomposeSelectedSkill() {
  if (!state.selectedSkillId) return;
  $("#skillResult").textContent = "Decomposing skill into SKILL.md and agent graph...";
  try {
    const result = await postJson("/api/skills/decompose", { skill_id: state.selectedSkillId, actor: "local-user" });
    $("#skillResult").textContent = formatSkillActionResult(result);
    await safeRefreshSkills();
    await safeRefreshReviewDashboard();
    await selectSkill(state.selectedSkillId);
  } catch (error) {
    $("#skillResult").textContent = `Skill decomposition failed: ${error.message}`;
  }
}

async function approveSelectedSkill(decision) {
  if (!state.selectedSkillId) return;
  $("#skillResult").textContent = `${decision === "approve" ? "Approving" : "Rejecting"} skill...`;
  try {
    const result = await postJson("/api/skills/approval", {
      skill_id: state.selectedSkillId,
      decision,
      rationale: $("#skillApprovalRationale").value || "",
      actor: "local-user",
    });
    $("#skillResult").textContent = formatSkillActionResult(result);
    await safeRefreshSkills();
    await safeRefreshReviewDashboard();
    await selectSkill(state.selectedSkillId);
    showToast(decision === "approve" ? "Skill approved" : "Skill rejected", state.selectedSkillId, "success");
  } catch (error) {
    $("#skillResult").textContent = `Skill approval update failed: ${error.message}`;
    showToast("Skill approval update failed", error.message, "error");
  }
}

async function runSelectedSkill() {
  if (!state.selectedSkillId) return;
  const manualRequest = $("#skillRunRequest").value.trim();
  if (!manualRequest) {
    $("#skillResult").textContent = "Add a manual request before running the skill.";
    return;
  }
  const sourceInput = {
    email_input: $("#skillRunEmail").value,
    calendar_input: $("#skillRunCalendar").value,
    teams_input: $("#skillRunTeams").value,
    knowledge_context: $("#skillRunKnowledge").value,
  };
  if (!(await confirmSkillFollowUpGate(sourceInput, "skills"))) return;
  if (!(await confirmTwinScopedAction("run this skill"))) return;
  $("#skillResult").textContent = "Running approved skill...";
  try {
    const result = await postJson("/api/skills/run", {
      skill_id: state.selectedSkillId,
      manual_request: manualRequest,
      email_input: $("#skillRunEmail").value,
      calendar_input: $("#skillRunCalendar").value,
      teams_input: $("#skillRunTeams").value,
      knowledge_context: $("#skillRunKnowledge").value,
      graph_context_packet: state.graphSkillContextPacket || null,
      twin: state.activeTwin,
      actor: "local-user",
    });
    $("#skillResult").textContent = formatSkillRunResult(result);
    await safeRefreshReviewDashboard();
    await safeRefreshSkillRuns();
    showToast("Skill run completed", result.run_id || state.selectedSkillId, "success");
  } catch (error) {
    $("#skillResult").textContent = `Skill run failed: ${error.message}`;
    showToast("Skill run failed", error.message, "error");
  }
}

function formatSkillActionResult(result) {
  const spec = result.skill?.spec || {};
  const lint = result.lint || result.skill?.lint || {};
  return [
    `Status: ${result.status || "-"}`,
    `Skill: ${spec.name || result.skill?.skill_id || "-"}`,
    `Folder: ${result.skill?.folder || "-"}`,
    `Risk: ${spec.risk_class || "-"}`,
    `Lint: ${lint.valid === undefined ? "-" : lint.valid ? "valid" : "needs attention"}`,
    ...(lint.errors?.length ? ["", "Lint errors:", ...lint.errors.map((item) => `- ${item}`)] : []),
  ].join("\n");
}

function formatSkillRunResult(result) {
  const output = result.result || {};
  const preflight = result.preflight || output.preflight || {};
  const boundary = result.boundary_decisions || output.boundary_decisions || {};
  return [
    `Status: ${result.status || "-"}`,
    `Run: ${result.run_id || "-"}`,
    `Skill: ${result.skill_name || result.skill_id || "-"}`,
    `Preflight: ${preflight.status || "-"} / ${preflight.source_quality || "-"}`,
    `Human gates: ${boundary.requires_human_detected ?? "-"}`,
    `Trace: ${result.trace_path || "-"}`,
    "",
    output.markdown || JSON.stringify(output, null, 2),
  ].join("\n");
}

function renderSkillRunHistory() {
  const target = $("#skillRunHistory");
  const filter = $("#runQualityFilter");
  if (filter) filter.value = state.skillRunQualityFilter;
  const visibleRuns = filteredSkillRuns();
  renderRunCompareSelectors(visibleRuns);
  if (!state.skillRuns.length) {
    target.innerHTML = renderEmptyState("No skill runs yet.", "Run approved skill", "openSkills");
    return;
  }
  if (!visibleRuns.length) {
    target.innerHTML = '<p class="empty">No runs match this source-quality filter.</p>';
    return;
  }
  const bestRunId = bestSkillRunId(visibleRuns);
  target.innerHTML = visibleRuns
    .map(
      (run) => {
        const readiness = run.preflight ? sourceReadinessFromPreflight(run.preflight) : sourceReadiness(run.inputs || {});
        const stages = Array.isArray(run.orchestration?.state_machine) ? run.orchestration.state_machine : [];
        const gateCount = Number(run.boundary_decisions?.requires_human_detected ?? run.approval_queue?.length ?? 0);
        const hasReviewAction = ["needs_rework", "wrong_priority", "missing_context", "rejected"].includes(run.review_state);
        return `
        <article class="activity-row queue-card skill-run-history-card ${dashboardPriorityClass("run", run.review_state)} ${run.run_id === bestRunId ? "best-run" : ""}">
          <div>
            <div class="queue-card-head">
              <span class="queue-kind">${escapeHtml(run.review_state || "unreviewed")}</span>
              ${renderQueueMeta([run.twin || "twin", formatShortDate(run.created_at || "")])}
            </div>
            <h3>${escapeHtml(run.skill_name || run.skill_id || "Skill run")} ${run.run_id === bestRunId ? '<span class="best-run-marker">Best current run</span>' : ""}</h3>
            <p>${escapeHtml(run.summary || "Skill run completed.")}</p>
            <p>${escapeHtml(formatApprovalStateSummary(run.approval_states || []))}</p>
            ${renderSourceQualityMini(readiness)}
            ${renderRunStageMini(stages, gateCount)}
            ${run.run_id === bestRunId ? renderBestRunExplanation(run) : ""}
            <code>${escapeHtml(run.trace_path || run.run_id || "")}</code>
          </div>
          <div class="run-row-actions queue-card-actions">
            <small class="run-row-meta">${escapeHtml(formatInlineCounts(run.kpi_signals || {}))}</small>
            <div class="action-group replay-actions" aria-label="Replay actions">
              <span>Replay</span>
              <button class="secondary small open-run-chat-btn" type="button" data-run-id="${escapeHtml(run.run_id)}">Open in Chat</button>
              <button class="secondary small inspect-run-btn" type="button" data-run-id="${escapeHtml(run.run_id)}">Inspect trace</button>
              <button class="secondary small run-again-btn" type="button" data-run-id="${escapeHtml(run.run_id)}">Run again</button>
              <button class="secondary small save-run-preset-btn" type="button" data-run-id="${escapeHtml(run.run_id)}">Save preset</button>
            </div>
            ${hasReviewAction
              ? `<div class="action-group review-actions" aria-label="Review actions">
                  <span>Review</span>
                  <button class="secondary small propose-refinement-btn" type="button" data-run-id="${escapeHtml(run.run_id)}">Propose refinement</button>
                </div>`
              : ""}
          </div>
        </article>
      `;
      },
    )
    .join("");
  target.querySelectorAll(".propose-refinement-btn").forEach((button) => {
    button.addEventListener("click", () => proposeRefinement(button.dataset.runId));
  });
  target.querySelectorAll(".open-run-chat-btn").forEach((button) => {
    button.addEventListener("click", () => openSkillRunInChat(button.dataset.runId));
  });
  target.querySelectorAll(".inspect-run-btn").forEach((button) => {
    button.addEventListener("click", () => openSkillRunDrawer(button.dataset.runId));
  });
  target.querySelectorAll(".run-again-btn").forEach((button) => {
    button.addEventListener("click", () => runAgainFromHistory(button.dataset.runId));
  });
  target.querySelectorAll(".save-run-preset-btn").forEach((button) => {
    button.addEventListener("click", () => saveRunAsInputPreset(button.dataset.runId));
  });
}

function filteredSkillRuns() {
  if (state.skillRunQualityFilter === "all") return state.skillRuns;
  return state.skillRuns.filter((run) => {
    const readiness = run.preflight ? sourceReadinessFromPreflight(run.preflight) : sourceReadiness(run.inputs || {});
    return readiness.level === state.skillRunQualityFilter;
  });
}

function bestSkillRunId(runs) {
  if (!runs.length) return "";
  return [...runs]
    .sort((a, b) => skillRunScore(b) - skillRunScore(a))[0]?.run_id || "";
}

function skillRunScore(run) {
  const sourceScore = (run.preflight ? sourceReadinessFromPreflight(run.preflight) : sourceReadiness(run.inputs || {})).readyCount;
  const reviewScore = reviewStateScore(run.review_state);
  const approvalPenalty = Number(run.boundary_decisions?.requires_human_detected ?? run.result?.approval_queue?.length ?? run.kpi_signals?.approval_count ?? 0) * 0.1;
  return reviewScore * 10 + sourceScore - approvalPenalty;
}

function renderBestRunExplanation(run) {
  const readiness = run.preflight ? sourceReadinessFromPreflight(run.preflight) : sourceReadiness(run.inputs || {});
  const approvalCount = Number(run.boundary_decisions?.requires_human_detected ?? run.result?.approval_queue?.length ?? run.kpi_signals?.approval_count ?? 0);
  const reasons = [
    `${readiness.readyCount}/4 source blocks ready`,
    `review state: ${run.review_state || "unreviewed"}`,
    approvalCount ? `${approvalCount} approval items` : "no approval friction detected",
  ];
  return `
    <details class="best-run-details">
      <summary>Why marked best</summary>
      <ul>${reasons.map((reason) => `<li>${escapeHtml(reason)}</li>`).join("")}</ul>
    </details>
  `;
}

function renderRunStageMini(stages, gateCount = 0) {
  if (!Array.isArray(stages) || !stages.length) {
    return gateCount ? `<div class="run-stage-mini"><span class="approval-required">${escapeHtml(gateCount)} human gates</span></div>` : "";
  }
  const stageText = stages
    .slice(0, 4)
    .map((stage) => `${stage.label || stage.key}: ${stage.status}`)
    .join(" · ");
  return `
    <div class="run-stage-mini">
      <span>${escapeHtml(stageText)}</span>
      ${gateCount ? `<span class="approval-required">${escapeHtml(gateCount)} human gates</span>` : ""}
    </div>
  `;
}

function renderRunCompareSelectors(runs = state.skillRuns) {
  const options = [
    '<option value="">Choose run</option>',
    ...runs.slice(0, 30).map((run) => {
      const label = `${run.skill_name || run.skill_id || "skill"} · ${formatShortDate(run.created_at)} · ${run.review_state || "unreviewed"}`;
      return `<option value="${escapeHtml(run.run_id)}">${escapeHtml(label)}</option>`;
    }),
  ].join("");
  ["#compareRunA", "#compareRunB"].forEach((selector) => {
    const node = $(selector);
    if (!node) return;
    const current = node.value;
    node.innerHTML = options;
    node.value = runs.some((run) => run.run_id === current) ? current : "";
  });
}

function renderSelectedRunComparison() {
  const runA = state.skillRuns.find((run) => run.run_id === $("#compareRunA").value);
  const runB = state.skillRuns.find((run) => run.run_id === $("#compareRunB").value);
  const target = $("#skillRunCompare");
  if (!runA || !runB) {
    target.innerHTML = '<p class="empty">Choose two runs to compare.</p>';
    return;
  }
  target.innerHTML = `
    <div class="compare-grid">
      ${renderRunCompareCard("Run A", runA)}
      ${renderRunCompareCard("Run B", runB)}
    </div>
    ${renderRunComparisonDelta(runA, runB)}
  `;
}

function renderRunCompareCard(label, run) {
  const result = run.result || {};
  const todos = Array.isArray(result.todos) ? result.todos.length : Number(run.kpi_signals?.todo_count || 0);
  const approvals = Array.isArray(result.approval_queue) ? result.approval_queue.length : Number(run.kpi_signals?.approval_count || 0);
  const timeline = Array.isArray(result.timeline) ? result.timeline.length : Number(run.kpi_signals?.timeline_count || 0);
  const inputs = run.inputs || {};
  const readiness = sourceReadiness(inputs);
  return `
    <article class="compare-card">
      <span class="badge">${escapeHtml(label)}</span>
      <h3>${escapeHtml(run.skill_name || run.skill_id || "Skill run")}</h3>
      <p>${escapeHtml(run.summary || result.summary || "Skill run completed.")}</p>
      <div class="metric-row compact-metrics">
        <span><strong>${escapeHtml(todos)}</strong>todos</span>
        <span><strong>${escapeHtml(approvals)}</strong>approvals</span>
        <span><strong>${escapeHtml(timeline)}</strong>timeline</span>
      </div>
      <p><strong>Review:</strong> ${escapeHtml(run.review_state || "unreviewed")}</p>
      ${renderSourceQualityMini(readiness)}
      <code>${escapeHtml(run.trace_path || run.run_id || "")}</code>
    </article>
  `;
}

function renderRunComparisonDelta(runA, runB) {
  const scoreA = runSourceCount(runA.inputs || {});
  const scoreB = runSourceCount(runB.inputs || {});
  const approvalsA = runA.result?.approval_queue?.length ?? Number(runA.kpi_signals?.approval_count || 0);
  const approvalsB = runB.result?.approval_queue?.length ?? Number(runB.kpi_signals?.approval_count || 0);
  const todosA = runA.result?.todos?.length ?? Number(runA.kpi_signals?.todo_count || 0);
  const todosB = runB.result?.todos?.length ?? Number(runB.kpi_signals?.todo_count || 0);
  return `
    <div class="compare-delta">
      <strong>${escapeHtml(compareRunSummary(runA, runB))}</strong>
      <span>Source completeness: ${escapeHtml(scoreA)} → ${escapeHtml(scoreB)}</span>
      <span>Todos: ${escapeHtml(todosA)} → ${escapeHtml(todosB)}</span>
      <span>Approvals: ${escapeHtml(approvalsA)} → ${escapeHtml(approvalsB)}</span>
    </div>
  `;
}

function compareRunSummary(runA, runB) {
  const scoreA = runSourceCount(runA.inputs || {});
  const scoreB = runSourceCount(runB.inputs || {});
  const reviewA = reviewStateScore(runA.review_state);
  const reviewB = reviewStateScore(runB.review_state);
  if (scoreB > scoreA && reviewB >= reviewA) return "Run B has stronger source grounding with equal or better review state.";
  if (scoreA > scoreB && reviewA >= reviewB) return "Run A has stronger source grounding with equal or better review state.";
  if (reviewB > reviewA) return "Run B has the stronger review outcome.";
  if (reviewA > reviewB) return "Run A has the stronger review outcome.";
  return "Runs are similar on source completeness and review outcome.";
}

function reviewStateScore(stateValue) {
  const scores = {
    useful: 4,
    approved: 4,
    unreviewed: 2,
    missing_context: 1,
    wrong_priority: 1,
    needs_rework: 1,
    rejected: 0,
  };
  return scores[stateValue || "unreviewed"] ?? 2;
}

function renderSourceQualityMini(readiness) {
  return `
    <div class="source-quality-mini ${escapeHtml(readiness.level)}">
      <span>${escapeHtml(readiness.label)}</span>
      <small>${escapeHtml(readiness.readyCount)}/4 ready${readiness.missing.length ? ` · missing ${escapeHtml(readiness.missing.join(", "))}` : ""}</small>
    </div>
  `;
}

function missingRunSourceLabels(inputs) {
  const sourceMap = [
    ["email_input", "email"],
    ["calendar_input", "calendar"],
    ["teams_input", "teams"],
    ["knowledge_context", "knowledge"],
  ];
  return sourceMap.filter(([key]) => !String(inputs[key] || "").trim()).map(([, label]) => label);
}

function runSourceCount(inputs) {
  return 4 - missingRunSourceLabels(inputs).length;
}

function sourceCompletenessLabel(inputs) {
  const ready = runSourceCount(inputs);
  const missing = missingRunSourceLabels(inputs);
  return missing.length ? `${ready}/4 ready; missing ${missing.join(", ")}` : "4/4 ready";
}

async function runAgainFromHistory(runId) {
  const loaded = openSkillRunInChat(runId);
  if (!loaded) return;
  const query = $("#queryInput").value.trim();
  if (!query) {
    setChatSkillStatus("Loaded the run, but no manual request was stored.", "error");
    return;
  }
  $("#chatForm").requestSubmit();
}

function openSkillRunInChat(runId) {
  const run = state.skillRuns.find((item) => item.run_id === runId);
  if (!run) return false;
  const skill = state.skills.find((item) => item.skill_id === run.skill_id);
  if (!skill || skill.status !== "approved") {
    setOutputStatus("#skillResult", "error", "Run cannot be loaded into chat", "This run belongs to a skill version that is not currently approved. Open the candidate from the review dashboard instead.");
    return false;
  }
  const inputs = run.inputs || {};
  state.activeChatSkillId = run.skill_id;
  state.appliedChatSkillIds = [run.skill_id];
  renderAppliedSkillsSelector();
  renderChatSkillMode();
  safeRefreshSkillInputPresets();
  $("#queryInput").value = inputs.manual_request || "";
  $("#chatSkillEmail").value = inputs.email_input || "";
  $("#chatSkillCalendar").value = inputs.calendar_input || "";
  $("#chatSkillTeams").value = inputs.teams_input || "";
  $("#chatSkillKnowledge").value = inputs.knowledge_context || "";
  renderSkillPreflight();
  showView("chat");
  addMessage("assistant", `Loaded prior run ${run.run_id} into the skill form. Adjust the sources or request, then run it again.`);
  return true;
}

function openSkillRunDrawer(runId) {
  const run = state.skillRuns.find((item) => item.run_id === runId);
  if (!run) return false;
  $("#drawerTitle").textContent = run.skill_name || run.skill_id || "Skill run trace";
  $("#drawerContent").innerHTML = renderSkillRunDrawer(run);
  $("#conceptDrawer").classList.add("open");
  $("#conceptDrawer").setAttribute("aria-hidden", "false");
  $("#drawerBackdrop").hidden = false;
  bindApprovalQueueActions($("#drawerContent"));
  $("#drawerContent").querySelector(".drawer-open-run-chat")?.addEventListener("click", () => {
    closeConceptDrawer();
    openSkillRunInChat(runId);
  });
  $("#drawerContent").querySelector(".drawer-propose-refinement")?.addEventListener("click", () => proposeRefinement(runId));
  $("#drawerContent").querySelector(".runtime-open-graph-packet")?.addEventListener("click", (event) => {
    event.stopPropagation();
    closeConceptDrawer();
    replaySkillRunGraphContext(runId);
  });
  return true;
}

function replaySkillRunGraphContext(runId, fallbackMetadata = null) {
  const run = state.skillRuns.find((item) => item.run_id === runId) || fallbackMetadata || {};
  const result = run.result || {};
  const runtimeContext = run.runtime_context || result.runtime_context || {};
  const packet = run.graph_context_packet || result.graph_context_packet || runtimeContext.graph_context_packet || {};
  if (!packet || !Object.keys(packet).length) {
    showToast("No graph packet attached", runId || "skill run", "error");
    return false;
  }
  const projection = packet.projection || {};
  state.graphReplayContext = {
    packet,
    runId: run.run_id || runId || "",
    skillName: run.skill_name || run.skill_id || result.skill_name || "Skill run",
    activatedAt: new Date().toISOString(),
  };
  state.graphReasoningPreset = projection.preset || "skill";
  state.graphIncludeDrafts = projection.include_drafts ?? true;
  state.graphNodeTypeFilter = "all";
  state.graphEdgeTypeFilter = "all";
  state.graphEdgeClassFilter = "all";
  state.graphReviewFilter = "all";
  state.graphDensityMode = projection.density || state.graphDensityMode || "balanced";
  state.graphLayoutMode = projection.layout || "topology";
  state.graphFocusMode = true;
  state.graphZoom = 1;
  state.graphSearch = "";
  const packetNodeKeys = graphPacketNodeKeys(packet);
  const graphNodeKeys = new Set((state.okfGraph?.nodes || []).map((node) => node.node_key));
  state.selectedGraphNodeKey = [...packetNodeKeys].find((key) => graphNodeKeys.has(key)) || "";
  state.selectedGraphEdgeKey = "";
  state.okfGraphNodeDetail = null;
  syncGraphControlValues();
  showView("graph");
  renderGraphCockpit();
  if (state.selectedGraphNodeKey) openGraphNode(state.selectedGraphNodeKey);
  showToast("Graph context replayed", `${(packet.nodes || []).length || 0} packet nodes`, "success");
  return true;
}

async function openSkillRunDrawerFromChat(runId) {
  if (!runId) return;
  if (openSkillRunDrawer(runId)) return;
  await safeRefreshSkillRuns();
  if (!openSkillRunDrawer(runId)) {
    showToast("Run detail unavailable", runId, "error");
  }
}

function renderSkillRunDrawer(run) {
  const result = run.result || {};
  const orchestration = run.orchestration || result.orchestration || {};
  const runtimeContext = run.runtime_context || result.runtime_context || {};
  const preflight = run.preflight || result.preflight || {};
  const evidence = run.evidence_package || result.evidence_package || {};
  const boundary = run.boundary_decisions || result.boundary_decisions || {};
  const graphContext = run.graph_context || result.graph_context || runtimeContext.graph_context || {};
  const graphPacket = run.graph_context_packet || result.graph_context_packet || runtimeContext.graph_context_packet || {};
  const agents = Array.isArray(run.task_agent_trace) ? run.task_agent_trace : Array.isArray(result.task_agent_trace) ? result.task_agent_trace : [];
  const stages = Array.isArray(orchestration.state_machine) ? orchestration.state_machine : [];
  const checkpoints = Array.isArray(orchestration.actor_checkpoints) ? orchestration.actor_checkpoints : [];
  const approvals = Array.isArray(run.approval_queue) ? run.approval_queue : Array.isArray(result.approval_queue) ? result.approval_queue : [];
  return `
    <section class="drawer-run-detail">
      <div class="drawer-run-actions">
        <button class="secondary small drawer-open-run-chat" type="button">Open in Chat</button>
        ${
          ["needs_rework", "wrong_priority", "missing_context", "rejected"].includes(run.review_state)
            ? '<button class="secondary small drawer-propose-refinement" type="button">Propose refinement</button>'
            : ""
        }
      </div>
      <div class="detail-grid">
        <span><strong>${escapeHtml(preflight.status || "unknown")}</strong>preflight</span>
        <span><strong>${escapeHtml(preflight.source_quality || evidence.quality || "unknown")}</strong>source quality</span>
        <span><strong>${escapeHtml(boundary.requires_human_detected ?? approvals.length)}</strong>human gates</span>
        <span><strong>${escapeHtml(agents.length)}</strong>task agents</span>
      </div>
      <section class="drawer-section">
        <h3>Runtime stages</h3>
        <div class="runtime-stage-list">${stages.length ? stages.map(renderRuntimeStage).join("") : '<span class="runtime-stage">No stages recorded</span>'}</div>
      </section>
      <section class="drawer-section">
        <h3>Preflight and evidence</h3>
        <p>${escapeHtml(renderPreflightText(preflight))}</p>
        ${Array.isArray(preflight.follow_up_questions) && preflight.follow_up_questions.length ? `<ul>${preflight.follow_up_questions.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>` : ""}
        ${renderEvidenceAnchors(evidence)}
      </section>
      <section class="drawer-section">
        <h3>Graph context</h3>
        <p>${escapeHtml(graphContext.usage || "skill_context_graph")}</p>
        <div class="detail-grid">
          <span><strong>${escapeHtml(String((graphContext.nodes || []).length || 0))}</strong>ranked nodes</span>
          <span><strong>${escapeHtml(String((graphContext.edges || []).length || 0))}</strong>relations</span>
        </div>
        <div class="runtime-grid">${renderSkillRunGraphPacketRuntime(graphPacket, run.run_id || "") || '<p class="empty">No user-prepared graph packet attached.</p>'}</div>
      </section>
      <section class="drawer-section">
        <h3>Actor checkpoints</h3>
        ${checkpoints.length ? `<div class="checkpoint-list">${checkpoints.map(renderActorCheckpoint).join("")}</div>` : '<p class="empty">No actor checkpoints recorded.</p>'}
      </section>
      <section class="drawer-section">
        <h3>Task-agent contracts</h3>
        ${agents.length ? `<div class="runtime-agent-grid">${agents.map(renderTaskAgentTrace).join("")}</div>` : '<p class="empty">No task-agent trace recorded.</p>'}
      </section>
      <section class="drawer-section">
        <h3>Decision boundaries</h3>
        <p>${escapeHtml(boundary.enforcement || "External actions remain human-gated.")}</p>
        ${renderBoundaryList("Autonomous", boundary.autonomous_actions || [])}
        ${renderBoundaryList("Requires human", boundary.requires_human_actions || [])}
      </section>
      ${renderSkillRunApprovalQueue(approvals, run.run_id || "", run.approval_states || [])}
      <section class="drawer-section">
        <h3>Output</h3>
        <p>${escapeHtml(result.summary || run.summary || "Skill run completed.")}</p>
        ${renderSkillRunKpis(result.kpi_signals || run.kpi_signals || {})}
      </section>
    </section>
  `;
}

function renderEvidenceAnchors(evidence) {
  const anchors = Array.isArray(evidence.source_anchors) ? evidence.source_anchors : [];
  if (!anchors.length) return '<p class="empty">No evidence anchors recorded.</p>';
  return `<div class="evidence-anchor-list">${anchors.map(renderEvidenceAnchor).join("")}</div>`;
}

function renderBoundaryList(label, items) {
  if (!Array.isArray(items) || !items.length) return "";
  return `
    <div class="boundary-list">
      <strong>${escapeHtml(label)}</strong>
      <ul>${items.slice(0, 6).map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul>
    </div>
  `;
}

async function saveRunAsInputPreset(runId) {
  const run = state.skillRuns.find((item) => item.run_id === runId);
  if (!run) return;
  const inputs = run.inputs || {};
  const defaultName = `${run.skill_name || "skill"} ${new Date().toISOString().slice(0, 10)}`;
  const name = await requestDecision({
    eyebrow: "Save preset",
    title: "Name this preset",
    body: "Save the run inputs as a reusable source preset for this skill.",
    confirmLabel: "Save preset",
    input: true,
    inputLabel: "Preset name",
    inputValue: defaultName,
  });
  if (!name) return;
  try {
    await postJson("/api/skills/input-presets", {
      name,
      skill_id: run.skill_id,
      manual_request: inputs.manual_request || "",
      email_input: inputs.email_input || "",
      calendar_input: inputs.calendar_input || "",
      teams_input: inputs.teams_input || "",
      knowledge_context: inputs.knowledge_context || "",
      actor: "local-user",
    });
    if (run.skill_id === state.activeChatSkillId) await safeRefreshSkillInputPresets();
    setOutputStatus("#skillResult", "success", `Saved preset "${name}"`, `Source run: ${run.run_id}`);
  } catch (error) {
    setOutputStatus("#skillResult", "error", "Preset save failed", error.message);
  }
}

async function proposeRefinement(runId) {
  if (!runId) return;
  try {
    const result = await postJson("/api/skills/refinements/propose", { run_id: runId, use_ai: true, actor: "local-user" });
    $("#skillResult").textContent = formatRefinementProposal(result.proposal);
    await safeRefreshSkillRefinements();
  } catch (error) {
    setOutputStatus("#skillResult", "error", "Refinement proposal failed", error.message);
  }
}

function renderSkillRefinements() {
  const target = $("#skillRefinements");
  if (!state.skillRefinements.length) {
    target.innerHTML = '<p class="empty">No refinement proposals yet.</p>';
    return;
  }
  target.innerHTML = state.skillRefinements
    .map(
      (proposal) => `
        <article class="activity-row queue-card skill-refinement-card ${dashboardPriorityClass("refinement", proposal.status)}">
          <div>
            <div class="queue-card-head">
              <span class="queue-kind">${escapeHtml(proposal.status || "pending_approval")}</span>
              ${renderQueueMeta([proposal.semver_change || "patch", proposal.ai_assistance?.used ? "ai-assisted" : "deterministic", proposal.review_state || ""])}
            </div>
            <h3>${escapeHtml(proposal.skill_name || proposal.skill_id || "Skill refinement")}</h3>
            <p>${escapeHtml(proposal.rationale || "")}</p>
            ${renderProposalChanges(proposal.proposed_changes || [])}
            <code>${escapeHtml(proposal.path || proposal.proposal_id || "")}</code>
          </div>
          <div class="queue-card-actions refinement-actions">
            <small>${escapeHtml(proposal.source_run_id || "")}</small>
            <button class="secondary small proposal-detail-btn" type="button" data-proposal-id="${escapeHtml(proposal.proposal_id)}">Details</button>
            ${
              proposal.status === "pending_approval"
                ? `<label class="compact-review-label" for="proposal-note-${escapeHtml(proposal.proposal_id)}">Review note</label>
                   <textarea id="proposal-note-${escapeHtml(proposal.proposal_id)}" class="proposal-review-note" rows="3" placeholder="Why approve or reject this proposal?"></textarea>
                   <div class="button-row tight">
                     <button class="secondary small proposal-review-btn" type="button" data-proposal-id="${escapeHtml(proposal.proposal_id)}" data-decision="approve">Approve proposal</button>
                     <button class="danger small proposal-review-btn" type="button" data-proposal-id="${escapeHtml(proposal.proposal_id)}" data-decision="reject">Reject proposal</button>
                   </div>`
                : proposal.status === "approved_pending_apply"
                  ? `<p class="review-saved">Approved. Ready to create pending skill version.</p>
                     <button class="secondary small proposal-apply-btn" type="button" data-proposal-id="${escapeHtml(proposal.proposal_id)}">Create pending version</button>`
                  : proposal.status === "applied_pending_skill_approval"
                    ? `<p class="review-saved">Candidate version created. Test it before approval.</p>
                       <div class="button-row tight">
                         <button class="secondary small proposal-shadow-btn" type="button" data-proposal-id="${escapeHtml(proposal.proposal_id)}">Shadow test</button>
                         <button class="secondary small proposal-candidate-btn" type="button" data-skill-id="${escapeHtml(proposal.applied_version_skill_id || "")}">Open candidate</button>
                       </div>`
                  : proposal.status === "rejected" && proposal.source_run_id
                    ? `<p class="review-saved">Rejected. The source run can receive a new proposal.</p>
                       <div class="button-row tight">
                         <button class="secondary small proposal-regenerate-btn" type="button" data-run-id="${escapeHtml(proposal.source_run_id)}">Propose again</button>
                         <button class="danger small proposal-archive-btn" type="button" data-proposal-id="${escapeHtml(proposal.proposal_id)}">Archive</button>
                       </div>`
                  : `<p class="review-saved">${escapeHtml(proposal.status || "")}</p>`
            }
          </div>
        </article>
      `,
    )
    .join("");
  target.querySelectorAll(".proposal-review-btn").forEach((button) => {
    button.addEventListener("click", () => reviewRefinementProposal(button.dataset.proposalId, button.dataset.decision));
  });
  target.querySelectorAll(".proposal-detail-btn").forEach((button) => {
    button.addEventListener("click", () => showRefinementProposalDetails(button.dataset.proposalId));
  });
  target.querySelectorAll(".proposal-apply-btn").forEach((button) => {
    button.addEventListener("click", () => applyRefinementProposal(button.dataset.proposalId));
  });
  target.querySelectorAll(".proposal-shadow-btn").forEach((button) => {
    button.addEventListener("click", () => shadowRunRefinementProposal(button.dataset.proposalId));
  });
  target.querySelectorAll(".proposal-candidate-btn").forEach((button) => {
    button.addEventListener("click", () => openSkillFromDashboard(button.dataset.skillId));
  });
  target.querySelectorAll(".proposal-regenerate-btn").forEach((button) => {
    button.addEventListener("click", () => proposeRefinement(button.dataset.runId));
  });
  target.querySelectorAll(".proposal-archive-btn").forEach((button) => {
    button.addEventListener("click", () => archiveRefinementProposal(button.dataset.proposalId));
  });
}

function renderProposalChanges(changes) {
  if (!changes.length) return "";
  return `
    <details class="proposal-changes">
      <summary>Proposed changes</summary>
      <ul>${changes.map((item) => `<li><strong>${escapeHtml(item.target || "")}</strong>: ${escapeHtml(item.diff || "")}</li>`).join("")}</ul>
    </details>
  `;
}

async function reviewRefinementProposal(proposalId, decision) {
  if (!proposalId || !decision) return;
  const note = $(`#proposal-note-${CSS.escape(proposalId)}`)?.value || "";
  try {
    const result = await postJson("/api/skills/refinements/review", {
      proposal_id: proposalId,
      decision,
      note,
      actor: "local-user",
    });
    $("#skillResult").textContent = formatRefinementProposal(result.proposal);
    await safeRefreshSkillRefinements();
    await safeRefreshSkills();
    showToast(decision === "approve" ? "Proposal approved" : "Proposal rejected", proposalId, "success");
  } catch (error) {
    setOutputStatus("#skillResult", "error", "Proposal review failed", error.message);
    showToast("Proposal review failed", error.message, "error");
  }
}

function showRefinementProposalDetails(proposalId) {
  const proposal = state.skillRefinements.find((item) => item.proposal_id === proposalId);
  $("#skillResult").textContent = formatRefinementProposal(proposal);
}

async function applyRefinementProposal(proposalId) {
  if (!proposalId) return;
  try {
    const result = await postJson("/api/skills/refinements/apply", {
      proposal_id: proposalId,
      actor: "local-user",
    });
    $("#skillResult").textContent = [
      `Apply status: ${result.status}`,
      `New skill: ${result.skill?.spec?.name || result.skill?.skill_id || "-"}`,
      `New status: ${result.skill?.config?.status || "-"}`,
      `Version: ${result.skill?.config?.version || "-"}`,
      `Folder: ${result.skill?.folder || "-"}`,
      "",
      "The new skill version is pending approval. The current approved version remains active until you approve the new one.",
    ].join("\n");
    await safeRefreshSkillRefinements();
    await safeRefreshSkills();
    if (result.skill?.skill_id) await selectSkill(result.skill.skill_id);
    showToast("Pending skill version created", result.skill?.skill_id || proposalId, "success");
  } catch (error) {
    setOutputStatus("#skillResult", "error", "Apply refinement failed", error.message);
    showToast("Apply refinement failed", error.message, "error");
  }
}

async function shadowRunRefinementProposal(proposalId) {
  if (!proposalId) return;
  try {
    const result = await postJson("/api/skills/refinements/shadow-run", {
      proposal_id: proposalId,
      twin: state.activeTwin,
      actor: "local-user",
    });
    $("#skillResult").textContent = [
      `Shadow run: ${result.shadow?.shadow_id || "-"}`,
      `Candidate: ${result.shadow?.candidate_skill_id || "-"}`,
      `Version: ${result.shadow?.candidate_version || "-"}`,
      `Source run: ${result.shadow?.source_run_id || "-"}`,
      "",
      result.shadow?.result?.markdown || JSON.stringify(result.shadow?.result || {}, null, 2),
    ].join("\n");
    await safeRefreshSkillRefinements();
    await safeRefreshReviewDashboard();
    showToast("Shadow test completed", result.shadow?.shadow_id || proposalId, "success");
  } catch (error) {
    setOutputStatus("#skillResult", "error", "Shadow test failed", error.message);
    showToast("Shadow test failed", error.message, "error");
  }
}

async function archiveRefinementProposal(proposalId) {
  if (!proposalId) return;
  const confirmed = await requestDecision({
    eyebrow: "Refinement cleanup",
    title: "Archive this proposal?",
    body: "Closed refinement proposals leave the active queue but remain in the local refinement files.",
    confirmLabel: "Archive proposal",
    danger: true,
  });
  if (!confirmed) return;
  try {
    const result = await postJson("/api/skills/refinements/archive", {
      proposal_id: proposalId,
      rationale: "Archived from Skills UI cleanup action.",
      actor: "local-user",
    });
    $("#skillResult").textContent = formatRefinementProposal(result.proposal);
    await safeRefreshSkillRefinements();
    await safeRefreshReviewDashboard();
    await safeRefreshSkillRuns();
  } catch (error) {
    setOutputStatus("#skillResult", "error", "Archive proposal failed", error.message);
  }
}

function formatRefinementProposal(proposal) {
  if (!proposal) return "No proposal returned.";
  const changes = proposal.proposed_changes || [];
  const review = proposal.human_review || {};
  const ai = proposal.ai_assistance || {};
  const impacts = proposal.quality_criteria_impacts || [];
  const shadowTests = proposal.shadow_tests || [];
  const comparison = proposal.run_comparison || null;
  return [
    `Refinement proposal: ${proposal.proposal_id}`,
    `Status: ${proposal.status}`,
    `Skill: ${proposal.skill_name}`,
    `Source run: ${proposal.source_run_id}`,
    `Generation: ${proposal.generation_mode || "deterministic"}`,
    `AI assistance: ${ai.used ? "used" : "not used"}${ai.reason ? ` - ${ai.reason}` : ""}`,
    `SemVer: ${proposal.semver_change}`,
    `Review: ${review.decision || "-"} ${review.note ? `- ${review.note}` : ""}`,
    `Applied version: ${proposal.applied_version || "-"}`,
    `Applied candidate skill: ${proposal.applied_version_skill_id || "-"}`,
    `Applied folder: ${proposal.applied_folder || "-"}`,
    `Latest shadow: ${proposal.latest_shadow_id || "-"}`,
    "",
    proposal.rationale || "",
    "",
    "Proposed changes:",
    ...changes.map((item) => `- ${item.target}: ${item.diff}`),
    ...(impacts.length ? ["", "Quality criteria impacts:", ...impacts.map((item) => `- ${typeof item === "string" ? item : JSON.stringify(item)}`)] : []),
    ...(comparison ? formatRunComparison(comparison) : []),
    ...(shadowTests.length ? ["", "Shadow test history:", ...shadowTests.map(formatShadowTestLine)] : []),
    "",
    proposal.safety_note || "",
  ].join("\n");
}

function formatRunComparison(comparison) {
  const source = comparison.source || {};
  const shadow = comparison.shadow || {};
  const delta = comparison.delta || {};
  return [
    "",
    "Run comparison:",
    `- Original run: ${comparison.source_run_id || "-"} | todos ${source.todo_count ?? 0} | approvals ${source.approval_count ?? 0}`,
    `- Shadow run: ${comparison.shadow_id || "-"} | todos ${shadow.todo_count ?? 0} | approvals ${shadow.approval_count ?? 0}`,
    `- Top priority changed: ${delta.top_priority_changed ? "yes" : "no"}`,
    "",
    "KPI signal deltas:",
    ...formatKpiDeltas(delta.kpi_signals || {}),
    "",
    "Original top priorities:",
    ...formatPriorityLines(source.top_priorities || []),
    "",
    "Shadow top priorities:",
    ...formatPriorityLines(shadow.top_priorities || []),
  ];
}

function formatKpiDeltas(kpis) {
  const entries = Object.entries(kpis);
  if (!entries.length) return ["- none"];
  return entries.map(([key, value]) => `- ${key}: ${value.source ?? 0} -> ${value.shadow ?? 0} (${formatSigned(value.delta ?? 0)})`);
}

function formatSigned(value) {
  return value > 0 ? `+${value}` : String(value);
}

function formatPriorityLines(items) {
  if (!items.length) return ["- none"];
  return items.map((item, index) => {
    const signals = Array.isArray(item.signals) && item.signals.length ? ` | signals: ${item.signals.join(", ")}` : "";
    return `- ${index + 1}. [${item.workstream || "-"}] ${item.what || "-"} | score ${item.score ?? 0}${signals}`;
  });
}

function formatShadowTestLine(shadow) {
  const result = shadow.result || {};
  const todos = Array.isArray(result.todos) ? result.todos.length : 0;
  const approvals = Array.isArray(result.approval_requests) ? result.approval_requests.length : 0;
  return `- ${shadow.shadow_id || "-"} | candidate ${shadow.candidate_skill_id || "-"} v${shadow.candidate_version || "-"} | todos ${todos} | approvals ${approvals}`;
}

function formatChatSkillRun(result) {
  const output = result.result || {};
  const steering = output.actor_steering || {};
  return [
    steering.twin ? `Twin steering: ${steering.twin} -> ${steering.skill || "selected skill"}` : "",
    steering.directive ? `Directive: ${steering.directive}` : "",
    steering.tone ? `Tone: ${steering.tone}` : "",
    steering.twin ? "" : "",
    output.markdown || JSON.stringify(output, null, 2),
    "",
    `Trace: ${result.trace_path || "-"}`,
  ].filter((line, index, lines) => line || lines[index - 1]).join("\n");
}

function dashboardAllConcepts(conceptReview = {}) {
  return [
    ...(conceptReview.pending || []),
    ...(conceptReview.voice_created || []),
    ...(conceptReview.needs_rework || []),
    ...(conceptReview.rejected || []),
  ];
}

function dashboardConceptMatchesCluster(concept = {}, cluster = state.dashboardClusterFilter) {
  if (!cluster) return true;
  const target = String(cluster).toLowerCase();
  const fields = [
    concept.cluster,
    concept.type,
    concept.path,
    ...(Array.isArray(concept.tags) ? concept.tags : []),
  ].map((value) => String(value || "").toLowerCase());
  return fields.some((value) => value === target || value.includes(target));
}

function filterDashboardConcepts(concepts) {
  const rows = Array.isArray(concepts) ? concepts : [];
  return state.dashboardClusterFilter ? rows.filter((concept) => dashboardConceptMatchesCluster(concept)) : rows;
}

function filterDashboardTraces(traces) {
  const rows = Array.isArray(traces) ? traces : [];
  return state.dashboardTraceQuadrant ? rows.filter((trace) => traceQuadrant(trace) === state.dashboardTraceQuadrant) : rows;
}

async function copyDashboardClusterPacket(cluster, concepts) {
  const rows = concepts.slice(0, 25).map((concept) => [
    `- ${concept.title || concept.path || "Concept"}`,
    `  - path: ${concept.path || "-"}`,
    `  - state: ${concept.review_state || "-"}`,
    `  - confidence: ${concept.confidence || 0}`,
    `  - action: review for duplicate, stale, low-confidence, or missing-evidence cleanup`,
  ].join("\n"));
  const packet = [
    `# Knowledge Cluster Cleanup Packet`,
    ``,
    `Cluster: ${cluster || "Unclustered"}`,
    `Generated: ${new Date().toISOString()}`,
    `Concept count: ${concepts.length}`,
    ``,
    `## Review Focus`,
    `- Merge duplicates inside this cluster.`,
    `- Promote source-backed concepts after human review.`,
    `- Mark stale or thin concepts as needs-rework.`,
    `- Keep deletion human-approved through the Knowledge Browser.`,
    ``,
    `## Concepts`,
    rows.join("\n") || "- no concepts visible in this scope",
  ].join("\n");
  const copied = await copyTextToClipboard(packet);
  showToast(copied ? "Cluster cleanup packet copied" : "Copy unavailable", cluster || "Knowledge cluster", copied ? "success" : "error");
}

function renderDashboardConcepts(selector, concepts, emptyText) {
  const target = $(selector);
  const visibleConcepts = filterDashboardConcepts(concepts);
  if (!visibleConcepts.length) {
    target.innerHTML = renderEmptyState(emptyText, "Open Knowledge Browser", "openKnowledge");
    return;
  }
  target.innerHTML = visibleConcepts
    .map(
      (concept) => {
        const voiceMeta = concept.voice_concept_category
          ? [
              `voice ${concept.voice_concept_category}`,
              `consistency ${Math.round((Number(concept.voice_consistency_score) || 0) * 100)}%`,
              `eligibility ${Math.round((Number(concept.voice_eligibility_score) || 0) * 100)}%`,
            ]
          : [];
        return `
        <article class="activity-row queue-card ${dashboardPriorityClass("concept", concept.review_state)}">
          <div class="queue-card-head">
            <span class="queue-kind">${escapeHtml(concept.type || "Concept")}</span>
            ${renderQueueMeta([concept.review_state || "pending-review", `confidence ${concept.confidence || 0}`, ...voiceMeta])}
          </div>
          <h3>${escapeHtml(concept.title || concept.path)}</h3>
          <code>${escapeHtml(concept.path || "")}</code>
          ${renderReviewCue("concept", concept)}
          <div class="queue-card-actions">
            <button class="secondary small dashboard-concept-review" type="button" data-path="${escapeHtml(concept.path)}">Review</button>
          </div>
        </article>
      `;
      },
    )
    .join("");
  target.querySelectorAll(".dashboard-concept-review").forEach((button) => {
    button.addEventListener("click", () => openConceptDrawer(button.dataset.path));
  });
}

