async function submitStructuredCanaryResultReview() {
  const path = $("#mcpCanaryResultArtifactPath")?.value || state.selectedMcpResultDeploymentPath || "";
  if (!path) {
    showToast("Canary result review blocked", "Select a hosted deployment artifact first.", "error");
    return;
  }
  const decision = $("#mcpCanaryResultDecision")?.value || "accept_with_followups";
  const outcome = $("#mcpCanaryResultOutcome")?.value || defaultCanaryOutcome(decision);
  const gatewayTraceId = $("#mcpCanaryResultGatewayTrace")?.value || "";
  const connectorTraceId = $("#mcpCanaryResultConnectorTrace")?.value || "";
  const externalArtifactUrl = $("#mcpCanaryResultExternalUrl")?.value || "";
  const resultSummary = $("#mcpCanaryResultSummary")?.value || "";
  const observedRisks = splitTextList($("#mcpCanaryResultRisks")?.value || "");
  const followUpActions = splitTextList($("#mcpCanaryResultFollowups")?.value || "");
  const confirmed = await requestDecision({
    eyebrow: "MCP canary result",
    title: "Record structured canary result?",
    body: `${path}\n\nDecision: ${decision}\nTrace evidence: ${gatewayTraceId || connectorTraceId || externalArtifactUrl || "not supplied"}\n\nThis writes a local review artifact only.`,
    confirmLabel: "Record result",
  });
  if (!confirmed) return;
  try {
    const result = await postJson("/api/mcp/canary-result-review", {
      deployment_artifact_path: path,
      decision,
      outcome,
      gateway_trace_id: gatewayTraceId,
      connector_trace_id: connectorTraceId,
      external_artifact_url: externalArtifactUrl,
      result_summary: resultSummary,
      observed_risks: observedRisks,
      follow_up_actions: followUpActions,
      actor: "local-user",
    });
    state.mcpCanaryResultReview = result;
    await refreshCanaryResultReviews(false);
    await refreshMcpStatus();
    showToast("Canary result review recorded", result.path || result.result_hash || "result ready", "success");
  } catch (error) {
    showToast("Canary result review failed", error.message, "error");
  }
}

function resetStructuredCanaryResultForm() {
  [
    "mcpCanaryResultGatewayTrace",
    "mcpCanaryResultConnectorTrace",
    "mcpCanaryResultExternalUrl",
    "mcpCanaryResultOutcome",
    "mcpCanaryResultSummary",
    "mcpCanaryResultRisks",
    "mcpCanaryResultFollowups",
  ].forEach((id) => {
    const field = $(`#${id}`);
    if (field) field.value = "";
  });
  const decision = $("#mcpCanaryResultDecision");
  if (decision) decision.value = "accept_with_followups";
}

function defaultCanaryOutcome(decision) {
  if (decision === "accept") return "Canary accepted with evidence attached.";
  if (decision === "reject") return "Canary rejected after evidence review.";
  if (decision === "rollback_required") return "Canary requires rollback before any further promotion.";
  return "Canary accepted with follow-up actions pending.";
}

