async function saveHostedCanaryRunbookEvidence(path, stepId) {
  if (!path || !stepId) return;
  const fields = {};
  $$(`[data-runbook-step="${cssEscape(stepId)}"]`).forEach((field) => {
    if (field.dataset.runbookField) fields[field.dataset.runbookField] = field.value || "";
  });
  const confirmed = await requestDecision({
    eyebrow: "Hosted MCP canary",
    title: "Save runbook evidence?",
    body: `${stepId}\n\nThis updates the local runbook artifact only. It does not execute MCP, call GitHub, or change gateway policy.`,
    confirmLabel: "Save evidence",
  });
  if (!confirmed) return;
  try {
    const result = await postJson("/api/mcp/hosted-canary-runbook-evidence", {
      path,
      step_id: stepId,
      values: fields,
      actor: "local-user",
      note: "updated from MCP cockpit",
    });
    state.mcpHostedCanaryRunbookArtifactDetail = {
      status: "ok",
      path: result.path,
      artifact: result.artifact,
      boundary: result.boundary,
    };
    await refreshHostedCanaryRunbookArtifacts(false);
    renderMcpCockpit();
    showToast("Runbook evidence saved", renderManualEvidenceSummary(result.manual_evidence_summary), "success");
  } catch (error) {
    showToast("Runbook evidence save failed", error.message, "error");
  }
}

function cssEscape(value) {
  if (window.CSS && typeof window.CSS.escape === "function") return window.CSS.escape(value);
  return String(value || "").replace(/["\\]/g, "\\$&");
}

