async function downloadBackfillManifest() {
  try {
    if (!state.migrationManifest) {
      await refreshMigrationManifest();
    }
    const manifest = state.migrationManifest;
    if (!manifest) {
      throw new Error("No manifest available yet.");
    }
    const payload = JSON.stringify(manifest, null, 2);
    const blob = new Blob([payload], { type: "application/json" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "intellectual-twin-backfill-manifest.json";
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(link.href);
    showToast("Manifest download ready", "Saved as intellectual-twin-backfill-manifest.json", "success");
  } catch (error) {
    showToast("Manifest download failed", error.message, "error");
  }
}

