async function reviewProductionGoNoGoArtifact(path, decision) {
  if (!path || !decision) return;
  const labels = {
    approve_for_rollout_review: "Sign off this go verdict for rollout review?",
    acknowledge_no_go: "Acknowledge this no-go verdict?",
    request_changes: "Request changes for this go/no-go artifact?",
    reject: "Reject this go/no-go artifact?",
  };
  const confirmed = await requestDecision({
    eyebrow: "Production go/no-go review",
    title: labels[decision] || "Review this go/no-go artifact?",
    body: `${path}\n\nThis records reviewer sign-off only. It does not deploy, promote MCP, set secrets, call GitHub, or change hosted state.`,
    confirmLabel: decision === "reject" ? "Reject artifact" : decision === "request_changes" ? "Request changes" : decision === "acknowledge_no_go" ? "Acknowledge no-go" : "Sign off",
    danger: decision === "reject",
  });
  if (!confirmed) return;
  const reviewer = window.prompt("Reviewer name", "local-user") || "local-user";
  const rationale = window.prompt("Reviewer rationale / note", "") || "";
  try {
    const result = await postJson("/api/production/go-no-go-signoff", {
      path,
      decision,
      reviewer,
      rationale,
      actor: "local-user",
    });
    const [artifacts, signoffs] = await Promise.all([
      getJson("/api/production/go-no-go-artifacts?limit=8"),
      getJson("/api/production/go-no-go-signoffs?limit=8"),
    ]);
    state.productionGoNoGoArtifactDetail = {
      path: result.path,
      file_hash: result.artifact_hash || "",
      artifact: result.artifact,
    };
    state.productionGoNoGoArtifacts = artifacts.artifacts || [];
    state.productionGoNoGoSignoffs = signoffs.signoffs || [];
    renderProductionCockpit();
    showToast("Go/no-go review recorded", decision, "success");
  } catch (error) {
    showToast("Go/no-go review failed", error.message, "error");
  }
}

