function githubBranchReviewEvidence(bridge = {}, reviewArtifacts = []) {
  const payload = bridge.sync_payload || {};
  const local = bridge.local_repo || {};
  const expectedBranch = bridge.expected_branch || "";
  const currentBranch = local.branch || "";
  const payloadHash = payload.payload_hash || "";
  const latest = reviewArtifacts.find((item) => item.review_accepted && item.decision === "reviewed_locally");
  const matches = Boolean(
    latest &&
    latest.payload_hash === payloadHash &&
    latest.expected_branch === expectedBranch &&
    latest.current_branch === currentBranch
  );
  if (matches) {
    return {
      ready: true,
      label: `Reviewed locally by ${latest.reviewer || "local-user"}`,
      detail: `${latest.path || "review artifact"} · ${String(latest.artifact_hash || "").slice(0, 12)}`,
      action: "Local review evidence matches the current payload and branch.",
      artifact: latest,
    };
  }
  if (latest) {
    return {
      ready: false,
      label: "Local review is stale",
      detail: `Latest accepted review is for ${latest.expected_branch || "unknown branch"} / ${(latest.payload_hash || "").slice(0, 12) || "unknown payload"}.`,
      action: "Record local review again after applying the current payload branch.",
      artifact: latest,
    };
  }
  return {
    ready: false,
    label: "Local review not recorded",
    detail: "Record human local review after branch, payload, working tree, and compare evidence are checked.",
    action: "Use Mark reviewed locally after reviewing the local diff.",
    artifact: null,
  };
}

function githubKnowledgePrChecklist(bridge = {}, localReviewEvidence = null) {
  const local = bridge.local_repo || {};
  const payload = bridge.sync_payload || {};
  const expectedBranch = bridge.expected_branch || "";
  const currentBranch = local.branch || "";
  const branchMatches = Boolean(expectedBranch && currentBranch === expectedBranch);
  const repoReady = Boolean(local.exists && local.is_git_repo);
  const payloadReady = Boolean(payload.absolute_path || payload.latest_path || payload.payload_hash);
  const compareReady = Boolean(bridge.compare_url);
  const dirty = Boolean(local.dirty);
  const items = [
    {
      key: "repo",
      label: "Local repo connected",
      state: repoReady ? "ready" : "blocked",
      detail: repoReady ? `${local.status || "git_repo"} at ${local.path || "configured path"}` : "Knowledge repository is not cloned as a local Git repo.",
      action: repoReady ? "Continue with branch and payload checks." : "Run the clone command from the bridge command pack.",
    },
    {
      key: "payload",
      label: "Latest payload exported",
      state: payloadReady ? "ready" : "blocked",
      detail: payloadReady ? `${payload.operation_count || 0} operation(s) · ${(payload.payload_hash || "").slice(0, 12) || "hash pending"}` : "No GitHub payload is available yet.",
      action: payloadReady ? "Use this payload for the next sync branch." : "Export a GitHub sync payload from Sync Export.",
    },
    {
      key: "branch",
      label: "Expected sync branch",
      state: branchMatches ? "ready" : "blocked",
      detail: expectedBranch ? `expected ${expectedBranch}${currentBranch ? ` · current ${currentBranch}` : ""}` : "Expected branch cannot be derived without a payload hash.",
      action: branchMatches ? "Review local changes, then push the branch." : "Run the apply-payload command with the expected branch name.",
    },
    {
      key: "working-tree",
      label: "Working tree review",
      state: repoReady && !dirty ? "ready" : "manual",
      detail: dirty ? "Local repo has uncommitted changes." : "No dirty local changes reported by the bridge.",
      action: dirty ? "Review and commit or discard local changes before push." : "Run git status before pushing to confirm the final diff.",
    },
    {
      key: "compare",
      label: "Compare page available",
      state: compareReady ? "manual" : "blocked",
      detail: compareReady ? bridge.compare_url : "Compare URL is unavailable until repo URL and expected branch are known.",
      action: compareReady ? "Open the compare page after pushing; GitHub must show changed files before PR review." : "Configure repo URL/path and export a payload.",
    },
    {
      key: "local-review",
      label: "Local diff reviewed",
      state: localReviewEvidence?.ready ? "ready" : "manual",
      detail: localReviewEvidence?.detail || "No local review evidence recorded.",
      action: localReviewEvidence?.action || "Record local review after checking the branch diff.",
    },
    {
      key: "review",
      label: "Human PR review",
      state: branchMatches && compareReady ? "manual" : "blocked",
      detail: "Merge is never automatic from the local MVP.",
      action: branchMatches && compareReady ? "Push the branch, open or update the PR, then review changed Markdown before merge." : "Complete branch and compare checks before requesting review.",
    },
  ];
  const readyCount = items.filter((item) => item.state === "ready").length;
  const next = items.find((item) => item.state === "blocked") || items.find((item) => item.state === "manual");
  return {
    items,
    ready_count: readyCount,
    check_count: items.length,
    next_action: next?.action || "Knowledge-base PR handoff is ready for human review.",
  };
}

