function renderProductionEnvChecklist(readiness = {}) {
  const target = $("#productionEnvChecklist");
  if (!target) return;
  const envGuide = state.productionEnvGuide || {};
  const checks = Array.isArray(readiness.checks) ? readiness.checks : [];
  if (!checks.length) {
    target.innerHTML = "";
    return;
  }
  const envRows = checks.flatMap((check) =>
    (Array.isArray(check.env) ? check.env : []).map((envName) => ({
      envName,
      category: check.category || "production",
      ready: Boolean(check.ready),
      gate: check.label || check.name || "Production gate",
      detail: check.detail || "",
    })),
  );
  const uniqueRows = [];
  const seen = new Set();
  envRows.forEach((row) => {
    if (seen.has(row.envName)) return;
    seen.add(row.envName);
    uniqueRows.push(row);
  });
  const readyCount = uniqueRows.filter((row) => row.ready).length;
  const guideGroups = Array.isArray(envGuide.groups) ? envGuide.groups : [];
  const guideCommands = envGuide.commands || {};
  const nextBundle = state.productionNextActionCommandBundle || {};
  const priorityCommand = nextBundle.priority_command || selectProductionPriorityCommand(Array.isArray(nextBundle.commands) ? nextBundle.commands : []);
  const blocker = nextBundle.blocker || readiness.next_configure_action || {};
  const validationMatrix = Array.isArray(readiness.validation_matrix)
    ? readiness.validation_matrix
    : Array.isArray(envGuide.validation_matrix)
      ? envGuide.validation_matrix
      : [];
  const hostedEnvReviewArtifacts = Array.isArray(state.hostedEnvValidationReviewArtifacts)
    ? state.hostedEnvValidationReviewArtifacts
    : [];
  const hostedEnvReviewDetail = state.hostedEnvValidationReviewArtifactDetail || {};
  const template = [
    "# Hosted production environment checklist",
    "# Fill values in the hosted secret manager or deployment environment.",
    ...uniqueRows.map((row) => `${row.envName}=`),
  ].join("\n");
  const grouped = uniqueRows.reduce((acc, row) => {
    acc[row.category] = acc[row.category] || [];
    acc[row.category].push(row);
    return acc;
  }, {});
  target.innerHTML = `
    <details class="production-env-drawer cockpit-disclosure">
      <summary>Environment variable checklist</summary>
      <section class="production-env-summary">
        <div>
          <span class="badge">Hosted config</span>
          <strong>${escapeHtml(readyCount)}/${escapeHtml(uniqueRows.length)} variables behind ready gates</strong>
          <p>Readiness gates are server-side. This list shows which deployment variables unlock each hosted production lane without exposing secret values.</p>
        </div>
        <button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(template)}">Copy .env checklist</button>
      </section>
      ${envGuide.boundary
        ? `<section class="production-handoff-summary">
            <div>
              <span class="badge">Azure App Service guide</span>
              <strong>${escapeHtml(envGuide.ready_count ?? 0)}/${escapeHtml(envGuide.variable_count ?? 0)} hosted variables ready</strong>
              <p>${escapeHtml(envGuide.boundary)}</p>
            </div>
            <span class="${envGuide.status === "ready" ? "ready" : "attention"}">${escapeHtml(envGuide.status || "needs_values")}</span>
          </section>`
        : ""}
      ${priorityCommand?.command
        ? `<section class="hosted-operator-bridge">
            <div>
              <span class="badge">Operator next command</span>
              <strong>${escapeHtml(priorityCommand.label || "Next operator command")}</strong>
              <p>${escapeHtml(blocker.action || readiness.next_action || priorityCommand.reason || "Run this first, then validate readiness again.")}</p>
              ${blocker.ui_anchor ? `<small>${escapeHtml(blocker.ui_anchor)}</small>` : ""}
            </div>
            <button class="secondary small source-copy-btn" type="button" data-copy-value="${escapeHtml(priorityCommand.command)}">Copy command</button>
            <pre>${escapeHtml(priorityCommand.command)}</pre>
          </section>`
        : ""}
      ${validationMatrix.length
        ? `<section class="hosted-validation-matrix">
            <div class="sync-payload-review-head compact">
              <div>
                <span class="badge">Hosted validation matrix</span>
                <strong>Postgres, object storage, and auth gates</strong>
                <p>Secret-safe validation plan for the first hosted foundations. It shows required env presence, validation endpoints, evidence targets, and why each gate matters.</p>
              </div>
              <button id="exportHostedEnvValidationReviewBtn" class="secondary small" type="button">Export env review</button>
            </div>
            <div class="hosted-validation-grid">
              ${validationMatrix.map(renderHostedValidationLane).join("")}
            </div>
            <div class="sync-ledger-list compact">
              ${hostedEnvReviewArtifacts.length
                ? hostedEnvReviewArtifacts.slice(0, 3).map(renderHostedEnvValidationReviewArtifactRow).join("")
                : '<p class="empty">No hosted environment validation review artifacts yet.</p>'}
            </div>
            ${hostedEnvReviewDetail?.artifact
              ? `<details class="sync-payload-json" open>
                  <summary>Selected hosted environment validation review</summary>
                  <pre class="output compact-output">${escapeHtml(JSON.stringify(hostedEnvReviewDetail.artifact, null, 2))}</pre>
                </details>`
              : ""}
          </section>`
        : ""}
      <div class="production-env-groups">
        ${Object.entries(grouped)
          .map(
            ([category, rows]) => `
              <article class="production-env-group">
                <h3>${escapeHtml(category)}</h3>
                <div>
                  ${rows
                    .map(
                      (row) => `
                        <span class="${row.ready ? "ready" : "missing"}">
                          <strong>${escapeHtml(row.envName)}</strong>
                          <small>${escapeHtml(row.gate)}</small>
                        </span>
                      `,
                    )
                    .join("")}
                </div>
              </article>
            `,
          )
          .join("")}
      </div>
      ${guideGroups.length
        ? `<details class="production-command-pack" open>
            <summary>Copy Azure/App Service setup commands</summary>
            <div class="production-env-groups">
              ${guideGroups.map((group) => `
                <article class="production-env-group">
                  <h3>${escapeHtml(group.category || "hosted")}</h3>
                  <div>
                    ${(group.variables || []).map((variable) => `
                      <span class="${variable.ready ? "ready" : "missing"}">
                        <strong>${escapeHtml(variable.name || "ENV")}</strong>
                        <small>${escapeHtml(variable.secret ? "secret placeholder" : variable.placeholder || "set value")}</small>
                      </span>
                    `).join("")}
                  </div>
                </article>
              `).join("")}
            </div>
            <div class="production-command-grid">
              ${renderProductionCommand("Azure App Service app settings", guideCommands.azure_app_settings || "# hosted app settings unavailable")}
              ${renderProductionCommand("Azure Key Vault secrets", guideCommands.azure_key_vault_secrets || "# hosted secret commands unavailable")}
              ${renderProductionCommand("App Service Key Vault references", guideCommands.azure_key_vault_references || "# key vault reference commands unavailable")}
              ${renderProductionCommand("Validate hosted configuration", guideCommands.validation || "# validation commands unavailable")}
            </div>
          </details>`
        : ""}
    </details>
  `;
  $("#exportHostedEnvValidationReviewBtn")?.addEventListener("click", exportHostedEnvValidationReviewArtifact);
  target.querySelectorAll(".hosted-env-review-open").forEach((button) => {
    button.addEventListener("click", () => openHostedEnvValidationReviewArtifact(button.dataset.path));
  });
  bindConceptSourceActions(target);
}

function renderHostedValidationLane(item) {
  const requiredEnv = item.required_env || {};
  const validation = Array.isArray(item.validation) ? item.validation : [];
  const evidence = Array.isArray(item.evidence) ? item.evidence : [];
  const missing = Array.isArray(item.missing_env) ? item.missing_env : [];
  return `
    <article class="hosted-validation-lane ${item.ready ? "ready" : "blocked"}">
      <span>${escapeHtml(item.status || (item.ready ? "ready" : "blocked"))}</span>
      <strong>${escapeHtml(item.label || item.id || "Hosted gate")}</strong>
      <p>${escapeHtml(item.purpose || "")}</p>
      ${item.detail ? `<small>${escapeHtml(item.detail)}</small>` : ""}
      <div class="hosted-validation-env">
        ${Object.entries(requiredEnv).map(([name, present]) => `
          <code class="${present ? "ready" : "missing"}">${escapeHtml(name)} ${present ? "set" : "missing"}</code>
        `).join("")}
      </div>
      <div class="hosted-validation-meta">
        <small><strong>Validate</strong>${escapeHtml(validation.join(" · ") || "GET /api/production/readiness")}</small>
        <small><strong>Evidence</strong>${escapeHtml(evidence.join(" · ") || "Production cockpit artifact")}</small>
        <small><strong>Risk</strong>${escapeHtml(item.risk || "Hosted rollout remains blocked.")}</small>
      </div>
      <em>${escapeHtml(missing.length ? item.next_action || "Configure missing variables." : item.next_action || "Export evidence after hosted validation.")}</em>
    </article>
  `;
}

function renderHostedEnvValidationReviewArtifactRow(item = {}) {
  const path = item.path || "";
  return `
    <article class="sync-ledger-row">
      <div>
        <strong>${escapeHtml(item.status || "blocked_reviewed")} · ${escapeHtml(item.decision || "resolve_hosted_env_blockers")}</strong>
        <p>${escapeHtml(`${item.readiness || "0/0"} checks · ${item.missing_lane_count ?? 0} missing hosted lane(s)`)}</p>
        <code>${escapeHtml(path)}</code>
      </div>
      <button class="secondary small hosted-env-review-open" type="button" data-path="${escapeHtml(path)}">Open review</button>
    </article>
  `;
}

function renderQualityCockpit() {
  const target = $("#qualityCockpit");
  if (!target) return;
  const readiness = state.productionReadiness || {};
  const checks = Array.isArray(readiness.checks) ? readiness.checks : [];
  const readyCount = readiness.ready_count ?? checks.filter((item) => item.ready).length;
  const checkCount = readiness.check_count ?? checks.length;
  const connectors = Array.isArray(state.mcpStatus?.connectors) ? state.mcpStatus.connectors : [];
  const activeMcp = state.mcpToolCalls.filter((call) => ["pending_approval", "approved"].includes(call.status)).length;
  const storage = state.storageStatus || {};
  const traceCount = state.traceExportStatus?.trace_count || 0;
  const smokeSteps = state.productionSmoke?.step_count || 0;
  const vectorStatus = state.vectorIndex?.status || "unchecked";
  const syncPending = state.syncStatus?.pending_count ?? "-";
  const migrationItems = state.migrationManifest?.summary?.item_count ?? 0;
  const telemetry = state.skillTelemetry || {};
  const telemetryActions = Array.isArray(telemetry.next_actions) ? telemetry.next_actions.length : 0;
  target.innerHTML = `
    <article class="cockpit-overview quality-overview">
      <div>
        <span class="badge">Production confidence</span>
        <h2>Four signals before hosted rollout</h2>
        <p>Track hosted checks, MCP approvals, skill gates, smoke traces, storage, vectors, and migration artifacts without exposing the full diagnostic surface by default.</p>
      </div>
      <div class="cockpit-overview-grid">
        <span class="${readyCount === checkCount && checkCount ? "ready" : "attention"}"><strong>${escapeHtml(readyCount)}/${escapeHtml(checkCount || 0)}</strong> prod checks</span>
        <span class="${activeMcp ? "attention" : "ready"}"><strong>${escapeHtml(activeMcp)}</strong> MCP approvals</span>
        <span class="${telemetryActions ? "attention" : "ready"}"><strong>${escapeHtml(telemetry.approval_pending ?? 0)}</strong> skill gates</span>
        <span><strong>${escapeHtml(smokeSteps || traceCount)}</strong> smoke steps</span>
      </div>
      <div class="quality-signal-row">
        <span>Storage: ${escapeHtml(storage.provider || "local")}</span>
        <span>Vector: ${escapeHtml(vectorStatus)}</span>
        <span>Skill memory: ${escapeHtml(telemetry.total_runs ?? 0)} runs</span>
        <span>Migration items: ${escapeHtml(migrationItems)}</span>
      </div>
    </article>
  `;
}

function renderSkillTelemetry() {
  const target = $("#skillTelemetryPanel");
  if (!target) return;
  const telemetry = state.skillTelemetry || {};
  const skills = Array.isArray(telemetry.skills) ? telemetry.skills : [];
  const actions = Array.isArray(telemetry.next_actions) ? telemetry.next_actions : [];
  target.innerHTML = `
    <div class="telemetry-summary">
      <span><strong>${escapeHtml(telemetry.total_runs ?? 0)}</strong>runs</span>
      <span><strong>${escapeHtml(telemetry.total_refinements ?? 0)}</strong>refinements</span>
      <span><strong>${escapeHtml(telemetry.approval_pending ?? 0)}</strong>open gates</span>
      <span><strong>${escapeHtml(skills.length)}</strong>skills tracked</span>
    </div>
    ${actions.length ? `<div class="telemetry-actions">${actions.map((item) => `<p>${escapeHtml(item)}</p>`).join("")}</div>` : ""}
    <div class="telemetry-skill-list">
      ${
        skills.length
          ? skills.slice(0, 8).map(renderSkillTelemetryCard).join("")
          : '<p class="empty">No skill runtime memory yet. Run an approved skill and review the output.</p>'
      }
    </div>
  `;
}

function renderSkillTelemetryCard(item) {
  const alerts = Array.isArray(item.quality_alerts) ? item.quality_alerts : [];
  const reviewStates = item.review_states || {};
  const sourceQuality = item.source_quality || {};
  const passRate = item.contract_pass_rate === null || item.contract_pass_rate === undefined ? "-" : item.contract_pass_rate;
  return `
    <article class="telemetry-skill-card ${alerts.length ? "attention" : "ready"}">
      <div>
        <span class="badge">${escapeHtml(item.status || "skill")}</span>
        <h3>${escapeHtml(item.skill_name || item.skill_id || "Skill")}</h3>
        <p>${escapeHtml(item.memory_note || "No runtime memory note.")}</p>
      </div>
      <div class="telemetry-metrics">
        <span><strong>${escapeHtml(item.health_score ?? "-")}</strong>health</span>
        <span><strong>${escapeHtml(item.run_count ?? 0)}</strong>runs</span>
        <span><strong>${escapeHtml(passRate)}</strong>contract</span>
        <span><strong>${escapeHtml(item.approval_pending ?? 0)}</strong>gates</span>
      </div>
      <small>Reviews: ${escapeHtml(formatInlineCounts(reviewStates)) || "-"}</small>
      <small>Source quality: ${escapeHtml(formatInlineCounts(sourceQuality)) || "-"}</small>
      ${alerts.length ? `<ul>${alerts.slice(0, 3).map((alert) => `<li>${escapeHtml(alert)}</li>`).join("")}</ul>` : ""}
    </article>
  `;
}

async function createMockMcpToolCall() {
  const connector = $("#mcpMockConnector").value.trim();
  const toolName = $("#mcpMockTool").value.trim();
  const summary = $("#mcpMockSummary").value.trim();
  if (!connector || !toolName || !summary) {
    $("#qualityResult").textContent = "Add connector, tool name, and request summary before creating a mock MCP call.";
    return;
  }
  $("#qualityResult").textContent = "Creating mock MCP approval item...";
  try {
    const result = await postJson("/api/mcp/tool-calls/mock", {
      connector,
      tool_name: toolName,
      request_summary: summary,
      twin: state.activeTwin,
      actor: "local-user",
    });
    $("#qualityResult").textContent = JSON.stringify(result, null, 2);
    await safeRefreshMcpStatus();
    await safeRefreshReviewDashboard();
    showToast("Mock MCP approval created", result.call?.call_id || connector, "success");
  } catch (error) {
    $("#qualityResult").textContent = `Mock MCP call failed: ${error.message}`;
    showToast("Mock MCP call failed", error.message, "error");
  }
}

async function reviewMcpToolCall(callId, decision, options = {}) {
  if (!callId || !decision) return;
  const rationale = await requestDecision({
    eyebrow: "MCP approval",
    title: `${decision === "approve" ? "Approve" : "Reject"} MCP tool call`,
    body: "Add the human rationale for this connector action.",
    confirmLabel: decision === "approve" ? "Approve" : "Reject",
    danger: decision !== "approve",
    input: true,
    inputLabel: "Rationale",
    inputValue: options.inputValue || "Reviewed from dashboard.",
  });
  if (rationale === null) return;
  try {
    await postJson("/api/mcp/tool-calls/review", {
      call_id: callId,
      decision,
      rationale,
      actor: "local-user",
    });
    await safeRefreshMcpStatus();
    await safeRefreshReviewDashboard();
    if (options.refreshHandoffPath) {
      await openVoiceAgentHandoffDetail(options.refreshHandoffPath);
    }
    showToast(decision === "approve" ? "MCP call approved" : "MCP call rejected", callId, "success");
  } catch (error) {
    setOutputStatus("#qualityResult", "error", "MCP review failed", error.message);
    showToast("MCP review failed", error.message, "error");
  }
}

async function executeMockMcpToolCall(callId, options = {}) {
  if (!callId) return;
  try {
    await postJson("/api/mcp/tool-calls/execute-mock", {
      call_id: callId,
      actor: "local-user",
    });
    await safeRefreshMcpStatus();
    await safeRefreshReviewDashboard();
    if (options.refreshHandoffPath) {
      await openVoiceAgentHandoffDetail(options.refreshHandoffPath);
    }
    showToast("Mock MCP call executed", callId, "success");
  } catch (error) {
    setOutputStatus("#qualityResult", "error", "Mock MCP execution failed", error.message);
    showToast("Mock MCP execution failed", error.message, "error");
  }
}

async function refreshTraceExportStatus() {
  const result = await getJson(`/api/trace-export/status?twin=${encodeURIComponent(state.activeTwin)}&limit=50`);
  state.traceExportStatus = result;
  const reviews = result.review_states || {};
  const reviewText = Object.entries(reviews).length
    ? ` Review states: ${Object.entries(reviews)
        .map(([key, value]) => `${key} ${value}`)
        .join(", ")}.`
    : "";
  $("#traceExportStatus").textContent = `${result.trace_count || 0} answer trace${result.trace_count === 1 ? "" : "s"} available for review export.`;
  $("#traceExportStatus").textContent += reviewText;
  renderQualityCockpit();
}

async function safeRefreshTraceExportStatus() {
  try {
    await refreshTraceExportStatus();
  } catch (error) {
    $("#traceExportStatus").textContent = "Trace export endpoint unavailable. Restart the local MVP server.";
    console.warn("Trace export status failed", error);
  }
}

function renderActivityList(selector, entries, emptyText) {
  const target = $(selector);
  if (!entries.length) {
    target.innerHTML = `<p class="empty">${emptyText}</p>`;
    return;
  }
  target.innerHTML = entries
    .map((entry) => {
      const detailRows = Object.entries(entry.details || {})
        .map(([key, value]) => `<div><dt>${escapeHtml(key)}</dt><dd>${escapeHtml(value)}</dd></div>`)
        .join("");
      return `
        <details class="activity-row activity-event">
          <summary>
            <span>
              <strong>${escapeHtml(entry.action || entry.heading || "Activity")}</strong>
              <time>${escapeHtml(entry.timestamp || "")}</time>
            </span>
            <span class="activity-event-count">${escapeHtml(Object.keys(entry.details || {}).length)} fields</span>
          </summary>
          ${detailRows ? `<dl class="compact-detail-list">${detailRows}</dl>` : '<p class="empty">No structured details stored.</p>'}
        </details>
      `;
    })
    .join("");
}

function applyActivityFilter() {
  const active = state.activityFilter || "all";
  $$("[data-activity-section]").forEach((section) => {
    section.hidden = active !== "all" && section.dataset.activitySection !== active;
  });
  const grid = $(".activity-timeline-grid");
  if (grid) grid.classList.toggle("compact-density", state.activityDensity === "compact");
  const densityButton = $("#activityDensityBtn");
  if (densityButton) {
    densityButton.textContent = state.activityDensity === "compact" ? "Compact" : "Comfortable";
    densityButton.setAttribute("aria-pressed", String(state.activityDensity === "compact"));
  }
}

function renderEvidenceList(evidence) {
  const target = $("#evidenceActivity");
  if (!evidence.length) {
    target.innerHTML = '<p class="empty">No evidence files stored yet.</p>';
    return;
  }
  target.innerHTML = evidence
    .map((item) => {
      const meta = [
        item.file_type ? `file: ${item.file_type}` : "",
        item.chunk_count ? `chunks: ${item.chunk_count}` : "",
        item.provider ? `provider: ${item.provider}` : "",
        item.model ? `model: ${item.model}` : "",
      ]
        .filter(Boolean)
        .join(" · ");
      return `
        <details class="activity-row activity-event evidence-event">
          <summary>
            <span>
              <strong>${escapeHtml(item.title || item.path)}</strong>
              <time>${escapeHtml(item.timestamp || "")}</time>
            </span>
            <span class="activity-event-count">${escapeHtml(item.type || "Evidence")}</span>
          </summary>
          <p>${escapeHtml(meta || "No extraction metadata stored.")}</p>
          <code>${escapeHtml(item.path)}</code>
          <div class="button-row tight">
            <button class="danger small evidence-delete" type="button" data-path="${escapeHtml(item.path)}">Delete</button>
          </div>
        </details>
      `;
    })
    .join("");
  target.querySelectorAll(".evidence-delete").forEach((button) => {
    button.addEventListener("click", () => deleteEvidence(button.dataset.path));
  });
}

function renderAnswerTraceList(traces) {
  const target = $("#answerTraceActivity");
  if (!traces.length) {
    target.innerHTML = '<p class="empty">No answer traces stored yet.</p>';
    return;
  }
  target.innerHTML = traces
    .map((trace) => {
      const statuses = Array.isArray(trace.guardrail_statuses) ? trace.guardrail_statuses.join(", ") : "";
      const review = trace.review_state || "unreviewed";
      return `
        <details class="activity-row activity-event trace-event">
          <summary>
            <span>
              <strong>${escapeHtml(trace.title || trace.query || "Answer trace")}</strong>
              <time>${escapeHtml(trace.timestamp || "")}</time>
            </span>
            <span class="activity-event-count">${escapeHtml(review)}</span>
          </summary>
          <p>confidence: ${escapeHtml(trace.confidence || 0)} · sources: ${escapeHtml(trace.source_count || 0)}${trace.retrieval_mode ? ` · retrieval: ${escapeHtml(trace.retrieval_mode)}` : ""}${statuses ? ` · guardrails: ${escapeHtml(statuses)}` : ""}</p>
          <code>${escapeHtml(trace.path)}</code>
          <div class="button-row tight">
            <button class="secondary small trace-review" type="button" data-path="${escapeHtml(trace.path)}">Review</button>
            <button class="secondary small trace-replay" type="button" data-path="${escapeHtml(trace.path)}">Replay</button>
          </div>
        </details>
      `;
    })
    .join("");
  target.querySelectorAll(".trace-review").forEach((button) => {
    button.addEventListener("click", () => openAnswerTraceDrawer(button.dataset.path));
  });
  target.querySelectorAll(".trace-replay").forEach((button) => {
    button.addEventListener("click", () => replayAnswerTrace(button.dataset.path));
  });
}

async function openAnswerTraceDrawer(path) {
  $("#drawerTitle").textContent = "Loading answer trace...";
  $("#drawerContent").innerHTML = '<p class="empty">Loading stored answer trace...</p>';
  $("#conceptDrawer").classList.add("open");
  $("#conceptDrawer").setAttribute("aria-hidden", "false");
  $("#drawerBackdrop").hidden = false;
  try {
    const detail = await postJson("/api/answer-traces/detail", { path });
    renderAnswerTraceDetail(detail);
  } catch (error) {
    $("#drawerTitle").textContent = "Trace unavailable";
    $("#drawerContent").innerHTML = `<p class="empty">Could not load trace: ${escapeHtml(error.message)}</p>`;
  }
}

async function replayAnswerTrace(path) {
  if (!path) return;
  const confirmed = await requestDecision({
    eyebrow: "Trace replay",
    title: "Replay this answer trace?",
    body: `${path}\n\nThis will run the stored query again and create a new trace.`,
    confirmLabel: "Replay trace",
  });
  if (!confirmed) return;
  try {
    const result = await postJson("/api/answer-traces/replay", { path });
    addMessage("user", result.query || "Replayed trace");
    addMessage("assistant", result.answer, result);
    await safeRefreshActivity();
    showToast("Trace replayed", path, "success");
  } catch (error) {
    addMessage("assistant", `Replay failed: ${error.message}`);
    showToast("Trace replay failed", error.message, "error");
  }
}

function renderAnswerTraceDetail(trace) {
  $("#drawerTitle").textContent = trace.title || "Answer trace";
  const sources = Array.isArray(trace.sources) ? trace.sources : [];
  const statuses = Array.isArray(trace.guardrail_statuses) ? trace.guardrail_statuses.join(", ") : "";
  const qualityTags = Array.isArray(trace.quality_tags) ? trace.quality_tags : [];
  $("#drawerContent").innerHTML = `
    <section class="detail-section">
      <h3>Trace Summary</h3>
      <dl class="detail-list">
        ${detailRow("Path", trace.path)}
        ${detailRow("Timestamp", trace.timestamp)}
        ${detailRow("Twin", trace.twin)}
        ${detailRow("Confidence", trace.confidence)}
        ${detailRow("Retrieval", trace.retrieval_mode)}
        ${detailRow("Sources", trace.source_count)}
        ${detailRow("Guardrails", statuses)}
        ${detailRow("Review state", trace.review_state || "unreviewed")}
        ${detailRow("Reviewed by", trace.reviewed_by)}
        ${detailRow("Reviewed at", trace.reviewed_at)}
        ${detailRow("Quality tags", qualityTags.join(", "))}
        ${detailRow("Hash", trace.provenance_hash)}
      </dl>
      <div class="trace-review-cue">
        <strong>Turn this answer into training signal</strong>
        <p>Choose the closest review signals. They become quality tags and a reviewer note for later refinement proposals.</p>
      </div>
      ${renderTraceReviewSignals(trace)}
      <label for="traceReviewStateSelect">Trace review</label>
      <select id="traceReviewStateSelect">
        <option value="unreviewed">unreviewed</option>
        <option value="approved">approved</option>
        <option value="needs-evidence">needs evidence</option>
        <option value="needs-rewrite">needs rewrite</option>
        <option value="unsafe">unsafe</option>
        <option value="not-useful">not useful</option>
      </select>
      <label for="traceQualityTagsInput">Quality tags</label>
      <input id="traceQualityTagsInput" type="text" placeholder="grounded, weak-source, demo-ready" value="${escapeHtml(qualityTags.join(", "))}" />
      <label for="traceReviewNoteInput">Reviewer note</label>
      <textarea id="traceReviewNoteInput" rows="3" placeholder="What should improve before reuse?">${escapeHtml(trace.review_note || "")}</textarea>
      <div class="button-row tight">
        <button class="secondary small trace-save-review" type="button" data-path="${escapeHtml(trace.path)}">Save review</button>
        <button class="secondary small drawer-replay" type="button" data-path="${escapeHtml(trace.path)}">Replay trace</button>
      </div>
    </section>
    ${renderTraceRefinementHandoff(trace)}
    <section class="detail-section">
      <h3>Query</h3>
      <p>${escapeHtml(trace.query || "")}</p>
    </section>
    <section class="detail-section">
      <h3>Answer</h3>
      <pre class="detail-body">${escapeHtml(trace.answer || "")}</pre>
    </section>
    <section class="detail-section">
      <h3>Retrieved Sources</h3>
      ${renderTraceSources(sources)}
    </section>
  `;
  $("#traceReviewStateSelect").value = trace.review_state || "unreviewed";
  bindTraceReviewSignals();
  bindConceptSourceActions($("#drawerContent"));
  $("#drawerContent").querySelector(".trace-save-review").addEventListener("click", () => saveTraceReview(trace.path));
  $("#drawerContent").querySelector(".drawer-replay").addEventListener("click", () => replayAnswerTrace(trace.path));
  $("#drawerContent").querySelector(".trace-copy-refinement-brief")?.addEventListener("click", () => copyTraceRefinementBrief(trace));
  $("#drawerContent").querySelector(".trace-export-review-pack")?.addEventListener("click", exportTraceReviewPackFromDrawer);
  $("#drawerContent").querySelector(".trace-open-review-queue")?.addEventListener("click", openTraceReviewQueue);
}

function traceReviewSignalOptions() {
  return [
    {
      tag: "grounded",
      label: "Well grounded",
      state: "approved",
      note: "Answer was sufficiently grounded in retrieved sources.",
    },
    {
      tag: "demo-ready",
      label: "Demo ready",
      state: "approved",
      note: "Answer can be reused as a high-quality example.",
    },
    {
      tag: "weak-source",
      label: "Weak source coverage",
      state: "needs-evidence",
      note: "Add stronger source evidence before reuse.",
    },
    {
      tag: "missing-context",
      label: "Missing context",
      state: "needs-evidence",
      note: "Relevant context was missing or sources were too thin.",
    },
    {
      tag: "wrong-priority",
      label: "Wrong priority",
      state: "needs-rewrite",
      note: "Answer prioritized the wrong workstream, stakeholder, or urgency signal.",
    },
    {
      tag: "voice-mismatch",
      label: "Voice mismatch",
      state: "needs-rewrite",
      note: "Answer did not sound like the active twin.",
    },
    {
      tag: "unsafe-claim",
      label: "Unsafe claim",
      state: "unsafe",
      note: "Answer made an unsupported or risky claim.",
    },
    {
      tag: "not-actionable",
      label: "Not actionable",
      state: "not-useful",
      note: "Answer was too vague to reuse as an action or decision input.",
    },
  ];
}

function renderTraceReviewSignals(trace) {
  const selected = new Set(Array.isArray(trace.quality_tags) ? trace.quality_tags : []);
  return `
    <div class="trace-review-signal-grid" aria-label="Trace review signals">
      ${traceReviewSignalOptions()
        .map(
          (signal) => `
            <label class="trace-signal">
              <input class="trace-signal-input" type="checkbox" value="${escapeHtml(signal.tag)}" data-state="${escapeHtml(signal.state)}" data-note="${escapeHtml(signal.note)}"${selected.has(signal.tag) ? " checked" : ""} />
              <span>
                <strong>${escapeHtml(signal.label)}</strong>
                <small>${escapeHtml(signal.tag)}</small>
              </span>
            </label>
          `,
        )
        .join("")}
    </div>
  `;
}

function bindTraceReviewSignals() {
  const root = $("#drawerContent");
  if (!root) return;
  root.querySelectorAll(".trace-signal-input").forEach((input) => {
    input.addEventListener("change", syncTraceReviewSignals);
  });
  syncTraceReviewSignals({ preserveExistingState: true });
}

function traceRefinementTarget(trace) {
  const tags = new Set(Array.isArray(trace.quality_tags) ? trace.quality_tags : []);
  const reviewState = trace.review_state || "unreviewed";
  if (reviewState === "unsafe" || tags.has("unsafe-claim")) {
    return {
      label: "Guardrails",
      action: "Tighten claim support, escalation, or unsafe-answer handling before reuse.",
    };
  }
  if (tags.has("voice-mismatch")) {
    return {
      label: "Actor persona",
      action: "Update persona style, tone, or steering examples so future answers sound like the active twin.",
    };
  }
  if (reviewState === "needs-evidence" || tags.has("weak-source") || tags.has("missing-context")) {
    return {
      label: "Knowledge evidence",
      action: "Add or improve source concepts before relying on this answer pattern.",
    };
  }
  if (reviewState === "needs-rewrite" || tags.has("wrong-priority") || tags.has("not-actionable")) {
    return {
      label: "Skill or answer behavior",
      action: "Use this trace as critique input for the relevant skill/run or answer prompt behavior.",
    };
  }
  if (reviewState === "approved" || tags.has("grounded") || tags.has("demo-ready")) {
    return {
      label: "Positive example",
      action: "Keep as a calibration example for future trace packs or eval examples.",
    };
  }
  return {
    label: "Review needed",
    action: "Review the trace first, then decide whether it belongs to evidence, persona, guardrail, or skill refinement.",
  };
}

function renderTraceRefinementHandoff(trace) {
  const target = traceRefinementTarget(trace);
  const tags = Array.isArray(trace.quality_tags) ? trace.quality_tags : [];
  const needsAction = ["needs-evidence", "needs-rewrite", "unsafe", "not-useful"].includes(trace.review_state || "") || tags.some((tag) => ["weak-source", "missing-context", "wrong-priority", "voice-mismatch", "unsafe-claim", "not-actionable"].includes(tag));
  return `
    <section class="detail-section trace-refinement-handoff ${needsAction ? "needs-action" : "calibration"}">
      <div>
        <span class="badge">Refinement handoff</span>
        <h3>${escapeHtml(target.label)}</h3>
        <p>${escapeHtml(target.action)}</p>
      </div>
      ${renderTraceImprovementPath(trace)}
      <div class="trace-refinement-brief">
        <span><strong>${escapeHtml(trace.review_state || "unreviewed")}</strong>review state</span>
        <span><strong>${escapeHtml(tags.join(", ") || "-")}</strong>quality tags</span>
        <span><strong>${escapeHtml(trace.source_count || 0)}</strong>sources</span>
      </div>
      <div class="button-row tight">
        <button class="secondary small trace-copy-refinement-brief" type="button">Copy refinement brief</button>
        <button class="secondary small trace-export-review-pack" type="button">Export trace pack</button>
        <button class="secondary small trace-open-review-queue" type="button">Open trace queue</button>
      </div>
      <small>Boundary: this creates review evidence only. Approved skills are changed through skill-run refinement proposals and human approval.</small>
    </section>
  `;
}

function traceImprovementPathSteps(trace) {
  const target = traceRefinementTarget(trace);
  const activeLabel = target.label;
  const steps = [
    {
      key: "review",
      label: "Review",
      detail: "human signal",
      active: activeLabel === "Review needed",
    },
    {
      key: "evidence",
      label: "Evidence",
      detail: "source gap",
      active: activeLabel === "Knowledge evidence",
    },
    {
      key: "persona",
      label: "Persona",
      detail: "voice or judgment",
      active: activeLabel === "Actor persona",
    },
    {
      key: "guardrail",
      label: "Guardrail",
      detail: "risk boundary",
      active: activeLabel === "Guardrails",
    },
    {
      key: "skill",
      label: activeLabel === "Positive example" ? "Calibration" : "Skill",
      detail: activeLabel === "Positive example" ? "good example" : "behavior change",
      active: activeLabel === "Skill or answer behavior" || activeLabel === "Positive example",
    },
  ];
  return steps;
}

function renderTraceImprovementPath(trace, options = {}) {
  const steps = traceImprovementPathSteps(trace);
  const active = steps.find((step) => step.active) || steps[0];
  return `
    <div class="trace-improvement-path ${options.compact ? "compact" : ""}" aria-label="Trace improvement path">
      <div class="trace-improvement-rail">
        ${steps
          .map(
            (step, index) => `
              <span class="${step.active ? "active" : ""}">
                <i>${escapeHtml(index + 1)}</i>
                <strong>${escapeHtml(step.label)}</strong>
                ${options.compact ? "" : `<small>${escapeHtml(step.detail)}</small>`}
              </span>
            `,
          )
          .join("")}
      </div>
      <p>${escapeHtml(active.label)} is the current recommended next stop for this trace.</p>
    </div>
  `;
}

function buildTraceRefinementBrief(trace) {
  const target = traceRefinementTarget(trace);
  const tags = Array.isArray(trace.quality_tags) ? trace.quality_tags.join(", ") : "";
  const sources = Array.isArray(trace.sources) ? trace.sources : [];
  const sourceLines = sources.slice(0, 8).map((source) => `- ${source.title || source.path || "source"} (${source.type || "source"}; confidence ${source.confidence || 0}) ${source.path || ""}`);
  const answerExcerpt = String(trace.answer || "-").length > 1600 ? `${String(trace.answer || "").slice(0, 1600)}...` : trace.answer || "-";
  return [
    "# Answer Trace Refinement Brief",
    "",
    `Trace: ${trace.path || "-"}`,
    `Twin: ${trace.twin || state.activeTwin || "-"}`,
    `Timestamp: ${trace.timestamp || "-"}`,
    `Review state: ${trace.review_state || "unreviewed"}`,
    `Quality tags: ${tags || "-"}`,
    `Recommended target: ${target.label}`,
    `Recommended action: ${target.action}`,
    "",
    "## Reviewer note",
    trace.review_note || "-",
    "",
    "## Query",
    trace.query || "-",
    "",
    "## Answer excerpt",
    answerExcerpt,
    "",
    "## Sources",
    ...(sourceLines.length ? sourceLines : ["- No retrieved sources recorded."]),
    "",
    "## Governance boundary",
    "Use this brief as refinement evidence. It does not change an approved skill, persona, or guardrail without human approval.",
  ].join("\n");
}

async function copyTraceRefinementBrief(trace) {
  const copied = await copyTextToClipboard(buildTraceRefinementBrief(trace));
  showToast(copied ? "Refinement brief copied" : "Copy unavailable", trace.path || "", copied ? "success" : "error");
}

